// 术语扩展 4——道学丹道 / 中医运气 / 择日 / 梦占 / 星占 / 姓名学 / 易经补充 / 黄历补充
import type { GlossaryTerm } from '@/lib/glossary-data'
export const EXT_TERMS_4: GlossaryTerm[] = [
  // ===== 道学丹道 (34) =====
  {slug:'dao',name:'道',pinyin:'Dào',english:'The Tao (Way)',category:'daoxue',shortDesc:'道家与道教最高概念，宇宙万物的本原与规律。',detail:'道是道家与道教最核心的概念，本义指道路，引申为宇宙万物的本原、总规律与最高真理。《道德经》开篇说「道可道，非常道」，认为能用语言说清的道就不是永恒不变的道。道家认为道无形无名、先天地而生，天地万物都由道化生，道无处不在却又不可名状。人生的修行，说到底就是体道、悟道、行道，最终与道合一。',related:['de','taiji','wuji']},
  {slug:'de',name:'德',pinyin:'Dé',english:'Virtue (Te)',category:'daoxue',shortDesc:'道在万物与人身上的体现，得道于心谓之德。',detail:'德是道家与道教的重要范畴，指道在万物与人身上的落实与体现。万物从道那里获得各自的禀性，人心中存养这份所得、依道而行，就是有德。《道德经》说「道生之，德畜之」，道生养万物，德畜养万物。德与道并称道德，道是体、德是用，修行者既要明道又要积德，德厚才能载道。',related:['dao','xing-ming']},
  {slug:'taiji',name:'太极',pinyin:'Tài Jí',english:'Supreme Ultimate',category:'daoxue',shortDesc:'天地未分前浑然一体的元气状态，阴阳未判之全体。',detail:'太极一语出自《易传》「易有太极，是生两仪」，指宇宙开初天地未分、阴阳未判时浑然一体的元气状态，是万物的源头。太极之中已含阴阳之机，动而生阳、静而生阴，两仪四象八卦由此展开。道家与宋明理学皆重太极：理学视太极为理与气之本，丹道则以人体为一小太极，修炼即运化自身阴阳，返归太极本然。',related:['wuji','yinyang','taijitu']},
  {slug:'wuji',name:'无极',pinyin:'Wú Jí',english:'Ultimateless',category:'daoxue',shortDesc:'太极之前无形无象的本然状态，无穷无际。',detail:'无极指无形无象、无边无际的宇宙本然状态，比太极更在其先。《道德经》说「复归于无极」，庄子亦言「游心于无穷」。宋儒周敦颐《太极图说》以「无极而太极」开篇，谓无极是本然之理境，太极是混沌未分之气，二者一体不二。道家修炼常以无极喻道体虚寂，主张万念放下、返本还元，回到无中生有的本源状态。',related:['taiji','dao','wuji-er-taiji']},
  {slug:'yinyang',name:'阴阳',pinyin:'Yīn Yáng',english:'Yin and Yang',category:'daoxue',shortDesc:'古人观察天地总结的对立统一观念，万物的两种基本属性。',detail:'阴阳是中华文化最根本的观念之一，最初指日光的向背，后推广为概括天地万物的对立统一范畴：天阳地阴、日阳月阴、男阳女阴、动阳静阴、热阳寒阴。阳主刚健、光明、生长、外向，阴主柔顺、幽暗、收藏、内守；二者互根互存、此消彼长、相互转化，如昼夜交替、寒暑往来。道家、易学与中医都以阴阳为理论基石，所谓一阴一阳之谓道。',related:['taiji','jingqishen']},
  {slug:'jingqishen',name:'精气神',pinyin:'Jīng Qì Shén',english:'Essence, Qi and Spirit',category:'daoxue',shortDesc:'人身三宝：精为物质基础，气为生命动力，神为意识主宰。',detail:'精气神是道教与中医共重的概念，被称为人身三宝。精指构成生命的有形物质精华，如生殖之精，主生长生育；气指弥漫周身的生命能量与动力，主推动温煦；神指精神意识与思维活动的总称，主生命活动的主宰。三者相互转化：精能化气，气能生神。丹道修炼由炼精化气、炼气化神、炼神还虚层层递进，使三宝充盈纯化，故有「精满不思淫，气满不思食，神满不思睡」之说。',related:['lianjing-huaqi','yuanshen','sandantian']},
  {slug:'yuanshen',name:'元神',pinyin:'Yuán Shén',english:'Primordial Spirit',category:'daoxue',shortDesc:'先天本具、不假思虑的灵明本体，即人之先天真性。',detail:'元神指人降生之前先天本具的灵明觉性，不经过后天学习思虑而自然灵照，是生命与精神的根本。道教认为元神常住人身，为识神所蔽；婴儿赤子之心近于元神，成人则多被后天识神用事。内丹修炼的关键，就是收摄六根、息灭妄念，使识神退位、元神主事，让先天真性自然显发，所谓「元神出兮识神藏」，这是返老还童、性命双修的根本功夫。',related:['shishen2','yangshen','jingqishen']},
  {slug:'shishen2',name:'识神',pinyin:'Shí Shén',english:'Consciousness Spirit',category:'daoxue',shortDesc:'后天习得的思虑分别之心，随六根攀缘外境而生。',detail:'识神指人出生后，依靠眼耳鼻舌身意六根接触外界而逐渐形成的意识心，好思虑、好分别、好执着，主管日常认知与情绪。道教认为识神属后天阴神，多动多耗，日夜劳神则精气日损；丹道修炼主张「识神死、元神活」，即通过静定功夫平息识神的纷扰，令其让位于清净的元神。此「识」读shí，与八字十神中的「食神」是两回事。',related:['yuanshen','jingqishen']},
  {slug:'sandantian',name:'三丹田',pinyin:'Sān Dān Tián',english:'Three Elixir Fields',category:'daoxue',shortDesc:'上中下三丹田：泥丸、绛宫、气海，丹道修炼三大要地。',detail:'丹田是道教内丹修炼的重要部位，分上中下三处，合称三丹田。上丹田在眉心深入处，名泥丸宫，主藏神，为性功所系；中丹田在胸口膻中深处，名绛宫，主藏气；下丹田在脐下三寸附近，为藏精纳气之所，是筑基下手、意守聚气的重点，又称气海、关元一带。丹道认为精、气、神各有所归，守下丹田炼精，守中丹田炼气，守上丹田炼神，三田贯通则周天可运。',related:['zhoutian','zhuji','jingqishen']},
  {slug:'zhoutian',name:'周天',pinyin:'Zhōu Tiān',english:'Celestial Cycle',category:'daoxue',shortDesc:'真气沿经脉循环一周，分小周天与大周天。',detail:'周天本指天体绕行一周，内丹借以形容真气在体内循环运行的功夫。打通任督二脉，使真气沿任脉下行、督脉上升循环一匝，称为小周天，是炼精化气阶段的主要功夫；真气进一步贯通手足十二正经与奇经八脉，全身气血周流无滞，称为大周天，属炼气化神境界。古人认为人身气血运行如天体周而复始，周天通畅则百病不生，故有「打通周天」之说。',related:['heche','rendu-ermai','lianjing-huaqi']},
  {slug:'heche',name:'河车',pinyin:'Hé Chē',english:'River Cart (Qi Conveyance)',category:'daoxue',shortDesc:'内丹以车载物喻真气沿督脉上升、任脉下降的搬运。',detail:'河车是内丹术比喻真气运行的术语，取车载货物运输之意，形容丹田真气沿督脉自下而上、再由任脉自上而下地升降循环。因督脉三关（尾闾、夹脊、玉枕）各有难通之处，古人又以羊车、鹿车、牛车分喻过关之力：尾闾关如羊车缓缓而行，夹脊关如鹿车奔跃，玉枕关最险如牛车力挽。真气过关上行又称「驾河车」，是打通小周天的形象说法。',related:['zhoutian','rendu-ermai','zhuji']},
  {slug:'rendu-ermai',name:'任督二脉',pinyin:'Rèn Dū Èr Mài',english:'Conception and Governing Vessels',category:'daoxue',shortDesc:'身前任脉总任诸阴，身后督脉总督诸阳，丹道周天之路。',detail:'任督二脉属奇经八脉中最重要的两条。任脉行于身体前正中线，总任一身之阴经，称阴脉之海；督脉行于身体后正中线，总督一身之阳经，称阳脉之海。中医以二脉主生殖与阳气；道教内丹则以任督为真气运行的主干道，督脉属阳主升、任脉属阴主降，真气自下丹田沿督脉上升、经任脉下降，循环一周即小周天。小说中「打通任督二脉」之说即由此而来。',related:['zhoutian','qijing-bamai','sandantian']},
  {slug:'zhuji',name:'筑基',pinyin:'Zhù Jī',english:'Foundation Building',category:'daoxue',shortDesc:'内丹入手功夫：填补亏损、调养身体，打好修炼根基。',detail:'筑基是内丹修炼的第一阶段功夫，好比盖房先打地基。修道者须先把亏损衰弱的身体调理复原，使精满、气足、神全，才能进行下一步的炼精化气。筑基之法不外收心、调息、守窍：平日清心寡欲以保精，行功调息绵绵以养气，意守丹田以凝神，配合饮食起居与导引锻炼。丹家说「筑基百日」是约数，根基深浅因人而异，基础不牢则后段功夫无从谈起。',related:['lianjing-huaqi','sandantian','taixi']},
  {slug:'lianjing-huaqi',name:'炼精化气',pinyin:'Liàn Jīng Huà Qì',english:'Refining Essence into Qi',category:'daoxue',shortDesc:'内丹三关之第一关，以元神之火烹炼元精化为真气。',detail:'炼精化气是内丹修炼「三关」中的初关功夫，又称百日关、小周天功夫。其法以意守下丹田为主，凝神入气穴，用元神真意之火烹炼先天元精，使精化为气；精气充盈后沿督脉上行，打通三关，形成小周天运转，故也称河车运转。此阶段重在「以神驭精、以精化气」，把容易走漏的生殖之精转化为周流全身的先天真气，为炼气化神奠定基础。',related:['lianqi-huanshen','zhoutian','zhuji']},
  {slug:'lianqi-huanshen',name:'炼气化神',pinyin:'Liàn Qì Huà Shén',english:'Refining Qi into Spirit',category:'daoxue',shortDesc:'内丹三关之第二关，气与神凝炼合一，结丹养胎。',detail:'炼气化神是内丹「三关」中的中关功夫，又称十月关、大周天功夫。精已化气之后，不再专行周天搬运，而是止火温养，使气与神相互凝炼、打成一片，达到神气合一的境界；功夫深时真气遍布全身，与神交融，在丹田凝成内丹之胎，须防散防漏，静养保固。此阶段重在「以气合神」，把气功转化为神功，使识神渐退、元神渐纯，为炼神还虚蓄积力量。',related:['lianjing-huaqi','lianshen-huanxu','wenyang']},
  {slug:'lianshen-huanxu',name:'炼神还虚',pinyin:'Liàn Shén Huán Xū',english:'Refining Spirit into Emptiness',category:'daoxue',shortDesc:'内丹三关之第三关，炼尽阴滓，神与太虚合一。',detail:'炼神还虚是内丹修炼的最高阶段，又称九年关、上关功夫。神已炼得纯阳之后，再进一步炼去神中余滓，令神体虚空融化，与宇宙太虚同体，无内无外、无我无物，返回先天无极之境，即所谓「虚空粉碎、与道合真」。丹家认为还虚之后形神俱妙，出神入化皆从此出，与天地同其长久。此境玄妙难言，历代丹经多只点到为止，谓到此方知「我命由天亦由我」的究竟。',related:['lianqi-huanshen','wuji','chushen']},
  {slug:'xingming-shuangxiu',name:'性命双修',pinyin:'Xìng Mìng Shuāng Xiū',english:'Cultivating Both Nature and Life',category:'daoxue',shortDesc:'既修心性又修命体，性与命并重不偏的修炼原则。',detail:'性命双修是道教内丹的修炼总原则。性指心性、精神与元神，属先天灵明；命指形体、气血与精气，属后天生命基础。只修性不修命，则身弱难支、禅定难久；只修命不修性，则徒有气力而心性不化，皆非正道。全真道北宗主张先性后命、以性摄命，南宗张伯端一系主张先命后性，然终归性命一体、双修并进，使身心俱炼、形神俱妙，是内丹区别于一般吐纳导引的根本所在。',related:['xing-ming','neidan','zhuji']},
  {slug:'xing-ming',name:'性命',pinyin:'Xìng Mìng',english:'Inner Nature and Life-Force',category:'daoxue',shortDesc:'道学核心范畴：性为先天心性本体，命为精气生命根基。',detail:'性命并称是道学与儒道养生共用的核心范畴。性指人先天本具的心性、元神，属精神层面的根源；命指人所禀受的精气与血肉之躯，属生命层面的根基。《易传》说「穷理尽性以至于命」，把穷究物理、尽显本性直至通达天命连成一贯。道家认为性命本为一体，性无命不立，命无性不存，故有「性命双修」之说；儒家则重在尽性立命，修养心性即是安身立命。',related:['xingming-shuangxiu','yuanshen','jingqishen']},
  {slug:'xuanguan-yiqiao',name:'玄关一窍',pinyin:'Xuán Guān Yī Qiào',english:'Mysterious Gate (Single Aperture)',category:'daoxue',shortDesc:'内丹最玄之窍，神气合一真机发动之处，非有形穴位。',detail:'玄关一窍又称玄牝、窍中窍，是内丹修炼中最神秘的概念，指炼丹时神气合一、先天真机发动的那一处关窍。历代丹家对其位置众说纷纭：有人说在脐下，有人说在眉间，也有人说不在身内、不在身外。主流认为它不是固定穴位，而是功夫到时自然呈现的「活窍」——念头不动、神气交会之际，恍惚之间真阳发动，方见玄关。故丹经有「玄关一窍，窍中藏窍」之叹，强求位置反而落空。',related:['qiangang','luding','zhuji']},
  {slug:'qiangang',name:'铅汞',pinyin:'Qiān Gǒng',english:'Lead and Mercury',category:'daoxue',shortDesc:'外丹矿物借喻内丹：真铅喻元精元气，真汞喻元神真意。',detail:'铅汞本指外丹烧炼的两种原料——铅与汞（水银），内丹兴起后借其名比喻人体内的药物。丹家以为，铅性沉伏属坎水，喻肾间先天元精元气，称真铅；汞性飞走属离火，喻心中元神真意，称真汞。炼丹的关键在以铅制汞、以静制动，使飞走的汞（神）伏定于铅（气），神气交媾、水火既济，如铅能制汞之飞扬。故丹经说「真铅制汞，汞自不飞」，全是比喻性命交修之理。',related:['luding','huohou','xuanguan-yiqiao']},
  {slug:'luding',name:'炉鼎',pinyin:'Lú Dǐng',english:'Furnace and Cauldron',category:'daoxue',shortDesc:'外丹烧炼之器，内丹借喻安炉立鼎、聚气凝神之所。',detail:'炉鼎原指外丹烧炼药物所用的器具：炉为生火加热之器，鼎为盛药烹炼之器。内丹借用其名：或以整个人身为鼎炉，精气神为药物，火候为功程；或以下丹田为炉，起火烹炼药物，以上丹田（泥丸）为鼎，汇聚凝炼神气，故有「安炉立鼎」之说。所谓安炉，即在身中找准修炼部位、安定身心；立鼎，则是聚神气于上以待凝结。炉鼎之说贯穿各家丹经，重在身内自造乾坤。',related:['qiangang','huohou','neidan']},
  {slug:'huohou',name:'火候',pinyin:'Huǒ Hòu',english:'Fire Timing (Alchemical Control)',category:'daoxue',shortDesc:'丹道行功中意念呼吸的运用与进退缓急的节度。',detail:'火候是内丹修炼最讲究的功夫。火指行功时以意念轻重、呼吸缓急为「火」，候指进退升降的时机节度。用意太过为武火，用以猛烹急炼、搬运周天；用意轻微若存若亡为文火，用以温养沐浴、防止火燥。进阳火、退阴符各有其时：子时进火、午时退符，抽添沐浴皆依火候而行。丹家说「圣人传药不传火」，盖火候全在临炉心传，分寸稍差即致走丹或火炎，故为丹道第一难事。',related:['choutian','muyu','wenyang','qiangang']},
  {slug:'choutian',name:'抽添',pinyin:'Chōu Tiān',english:'Extraction and Addition',category:'daoxue',shortDesc:'内丹火候功夫：抽坎填离，抽减有余、添补不足。',detail:'抽添是内丹火候术语，义本「抽坎填离」：坎卦中爻为阳，离卦中爻为阴，抽坎中一阳填补离中一阴，则离复为纯阳之乾，坎复为纯阴之坤，喻以精气补益元神、以水济火，使身心复还先天纯阳之体。行功中又引申为随时调节：神气有余则抽之使减，不足则添之使足，如《入药镜》所谓「水怕干，火怕寒」，时时保持水火均衡。抽添与进退、沐浴相配合，同属火候运用的大关节。',related:['huohou','qiangang','muyu']},
  {slug:'muyu',name:'沐浴',pinyin:'Mù Yù',english:'Bathing (Resting the Fire)',category:'daoxue',shortDesc:'内丹火候术语：行功至卯酉之时暂停武火，文火温养。',detail:'沐浴是内丹火候中的特殊阶段，取洗心涤虑、如沐浴净身之意。周天行功中，真气行至卯、酉之位（一说每日子午周天的卯酉二时），须停火息符，不再进阳火退阴符，只以文火绵绵温养片刻，防止火候太过而使药物走失或水干火炎。丹家比喻：武火烹炼如做饭须用大火，但火旺须防焦糊，中间须抽薪止沸、让其自然焖透，这一止火温养的过程便是沐浴。',related:['huohou','wenyang','choutian']},
  {slug:'wenyang',name:'温养',pinyin:'Wēn Yǎng',english:'Gentle Nourishing',category:'daoxue',shortDesc:'结丹之后的养护功夫：以文火绵绵温养丹体使其成熟。',detail:'温养是内丹结丹之后的保养功夫，又称养胎、乳哺。金丹初结、圣胎未固之时，不可再用武火猛炼，只宜以文火绵密照护，意守丹田，若存若亡，如母鸡孵卵、炉中煨药，令丹体渐渐凝固成熟。温养最忌三件事：一忌火寒则丹散，二忌火燥则丹飞，三忌念起则神驰。功夫纯熟、丹胎老成之后，方可言出神入化。各家丹法无论南北，温养都是必不可少的一程，所谓「防危虑险」即在此时。',related:['lianshen-huanxu','muyu','huohou']},
  {slug:'chushen',name:'出神',pinyin:'Chū Shén',english:'Spirit Egress',category:'daoxue',shortDesc:'阳神成熟后自顶门出入自由、神游身外的丹道境界。',detail:'出神是内丹修炼的高级境界，指温养功深、阳神老成之后，元神可自顶门（囟门、天门）脱出体外，出入自由，千里神游，故称出阳神。丹家以为到此地步仍须收回再炼，逐步加远出游距离，防其迷失；功夫圆满方能炼神还虚，与道合一。民间传说与小说中的「灵魂出窍」「元神出窍」即由此演化。出神之说属内丹理想境界，常人难以企及，丹经亦告诫未至温养成熟不可妄试，否则神散难收。',related:['yangshen','wenyang','lianshen-huanxu']},
  {slug:'yangshen',name:'阳神',pinyin:'Yáng Shén',english:'Yang Spirit',category:'daoxue',shortDesc:'元神炼纯、脱体而出的阳刚之身，与阴神相对。',detail:'阳神是道教内丹术语，指修炼者元神经过炼精化气、炼气化神等功夫炼得纯阳之后，脱离肉体而出的分身之体。丹家认为阳神有形有质、聚则成形、散则成气，出入自如，如《西游记》中孙悟空元神出窍一类想象即本于此。与之相对，未炼纯阳、仅凭静定勉强出窍者称阴神，无形无质，恍惚易散。阳神出窍是丹道大成的标志之一，出神之后仍须收回温养，进而炼神还虚、粉碎虚空，方为究竟。',related:['chushen','yuanshen','lianshen-huanxu']},
  {slug:'shijie',name:'尸解',pinyin:'Shī Jiě',english:'Corpse Liberation',category:'daoxue',shortDesc:'道教成仙之说：遗下形骸如蝉蜕，真身解脱而去。',detail:'尸解是道教关于修道者成仙方式的说法，指修炼者离世时留下躯壳，如蝉蜕壳、蛇蜕皮一般，真身却已解脱变化而去，故称尸解。传说形式多样：死后葬而空棺为解，借兵刃水火而化称兵解、水解、火解，又有托物代形之说。道教视尸解为成仙途径之一，常谓仙人「形解销化」；一般以为其品位略低于白日飞升、肉身成圣，但较凡俗之死已是超脱。汉魏以来史传方志中此类故事甚多。',related:['yangshen','chushen','fulu']},
  {slug:'fulu',name:'符箓',pinyin:'Fú Lù',english:'Talismans and Registers',category:'daoxue',shortDesc:'道教法术文书：符为天神图形文字，箓为神名簿册。',detail:'符箓是道教的重要法术传统，符与箓常并称。符指书写或绘制的神秘图形文字，道教认为符乃天地灵文，能召神劾鬼、镇邪治病；箓指记载神将功曹名号与奉道者名籍的簿册，授箓即取得相应神职与法术资格。以符箓法术为主的教派称符箓派，如正一道，道士画符念咒、符水治病、建坛行法皆属此类。符箓与斋醮相配合，是道教仪式与民间信仰的重要内容，至今民间仍可见其遗风。',related:['zhaijiao','shijie']},
  {slug:'zhaijiao',name:'斋醮',pinyin:'Zhāi Jiào',english:'Taoist Ritual (Fast and Offering)',category:'daoxue',shortDesc:'道教设坛祭祷的仪式总称：斋为洁身清心，醮为祭神。',detail:'斋醮是道教仪式的总称。斋本指祭祀前的清心洁身、素食止欲，以示虔诚；醮指设坛建醮、上章诵经、礼拜神真的祭祷法事。合而言之，凡为祈福禳灾、超度亡灵、谢土安宅而举行的道场仪式皆称斋醮，民间俗称打醮、做道场、作法事。斋醮科仪依事分类，规模有大有小，道士依科演法，配合符箓、经咒、步罡踏斗等法术。至今各地庙会或丧葬场合仍常见斋醮活动，是道教影响民间生活最直接的形式。',related:['fulu','shijie']},
  {slug:'neidan',name:'内丹',pinyin:'Nèi Dān',english:'Internal Alchemy',category:'daoxue',shortDesc:'以人体为炉鼎、精气神为药物、内炼结丹的修炼体系。',detail:'内丹是道教修炼的主流体系，相对外丹而言：不假炉火烧炼金石，而以自身为鼎炉，以体内精气神为药物，通过凝神调息、周天运转等功夫，在身内炼成金丹。其理论溯源于《周易参同契》，成熟于唐末五代，张伯端《悟真篇》出而大备，宋代以后内丹派别林立，有南北东西中五派之分。内丹以「性命双修」「三关返元」为纲领，把人体看作小宇宙，炼精化气、炼气化神、炼神还虚，追求延年益寿乃至与道合真，对气功养生影响深远。',related:['waidan','xingming-shuangxiu','zhoutian']},
  {slug:'waidan',name:'外丹',pinyin:'Wài Dān',english:'External Alchemy',category:'daoxue',shortDesc:'以炉鼎烧炼金石草药、服食以求长生的丹术。',detail:'外丹指用炉鼎炭火烧炼铅汞、硫磺、草药等，炼成金丹服食以求长生不死的方术，盛行于两汉至唐代。炼丹家认为服食金丹可肉身不朽、飞升成仙，帝王贵族多有热衷，但因火候难控、金石有毒，服丹致死者屡见不鲜，唐代多位皇帝即因此丧命，外丹遂渐衰落，被内丹取代。外丹虽属迷信，却在实践中积累了大量化学知识与冶炼经验，火药的发明即与炼丹活动密切相关，是中国古代科技史的重要一页。',related:['neidan','luding','qiangang']},
  {slug:'taixi',name:'胎息',pinyin:'Tāi Xī',english:'Embryonic Breathing',category:'daoxue',shortDesc:'行气养生术：如婴儿在母胎中以脐呼吸，不以口鼻。',detail:'胎息是道教行气养生的重要方法，谓修炼到高深处，口鼻呼吸几乎停止，如婴儿在母胎中不以口鼻呼吸，而靠丹田（脐）内息绵绵，故名胎息。练法多从调息入手：凝神入气穴，使呼吸深、细、匀、长，日久气息若有若无，似乎「内气不出，外气不入」，神气相依如胎孕。胎息能养精蓄锐、调节脏腑，是内丹筑基与气功修炼共重的基本功夫；《抱朴子》等道经视其为得道长生之阶。',related:['zhuji','bigu']},
  {slug:'bigu',name:'辟谷',pinyin:'Bì Gǔ',english:'Grain Abstinence',category:'daoxue',shortDesc:'道教养生方术：暂时不食五谷，服气饮水以清肠养气。',detail:'辟谷又称却谷、断谷，是道教养生方术之一，指在一段时间内不食五谷粮食，只饮水，或配合服气、食饵（药物、果实）维持生机，以求清肠净腑、减少浊气、激发先天元气。道教认为人体谷气多则神浊身重，辟谷可使身心轻健、利于入静修炼，故常与胎息、导引相配合。辟谷须循序渐进、量力而行，盲目绝食有害健康；今人常取其「轻断食」思路用于养生，已与传统方术有别。',related:['taixi','zhuji']},
  // ===== 中医运气 (24) =====
  {slug:'cangxiang',name:'藏象',pinyin:'Cáng Xiàng',english:'Visceral Manifestation',category:'zhongyi',shortDesc:'藏通脏：五脏深藏于内，功能显象于外的学说。',detail:'藏象是中医的核心理论。藏指深藏体内的五脏六腑，象指表现于外的征象；中医认为脏腑虽藏于内，其功能状态必然通过面色、舌象、脉象、体态、情志与声息显露于外，所谓「有诸内必形诸外」。医者即可由外在之象推知内在脏腑的虚实寒热。藏象学说以五脏为中心，联系六腑、五官九窍、四肢百骸与情志，构成一个整体的人体功能模型，是中医诊断与辨证论治的理论基础。',related:['wuzang-liufu','sizhen','qixue-jinye']},
  {slug:'jingluo',name:'经络',pinyin:'Jīng Luò',english:'Channels and Collaterals',category:'zhongyi',shortDesc:'气血运行、联络脏腑肢节的通道网络系统。',detail:'经络是中医理论中人体气血运行的通道系统，内连脏腑、外络肢节，纵横交错如网络遍布全身。经为主干，纵行深行，有十二正经与奇经八脉；络为分支，网络全身，浮络孙络细小密布。经络的功能在于运行气血、沟通表里上下、感应传导与调节平衡，所谓「经脉者，所以决死生、处百病、调虚实」。针灸、推拿、导引皆以经络学说为理论基础，循经取穴才能治病。',related:['qijing-bamai','shuxue','ziwu-liuzhu']},
  {slug:'qijing-bamai',name:'奇经八脉',pinyin:'Qí Jīng Bā Mài',english:'Eight Extraordinary Vessels',category:'zhongyi',shortDesc:'督任冲带、阴阳跷维八脉，统率调节十二正经。',detail:'奇经八脉指督脉、任脉、冲脉、带脉、阴跷脉、阳跷脉、阴维脉、阳维脉八条经脉。与十二正经不同，它们不直接隶属脏腑，也无表里配合关系，而是纵横交错于正经之间，起统率、联络、蓄溢调节全身气血的作用：督脉总督诸阳，任脉总任诸阴，冲脉为十二经之海，带脉约束纵行诸经。八脉中以任督最受重视——中医主生殖养生，道教内丹周天功夫也以打通任督为要。',related:['jingluo','rendu-ermai']},
  {slug:'shuxue',name:'腧穴',pinyin:'Shù Xué',english:'Acupoints',category:'zhongyi',shortDesc:'经络气血输注出入于体表的部位，即穴位穴道。',detail:'腧穴是人体经络气血输注出入于体表的特定部位，俗称穴位、穴道、孔穴。腧有输注之意，穴有空隙之意。全身经穴数百个，分布于十四经脉之上，各有所属脏腑与主治病症，如合谷治头面、足三里健脾胃。针灸、推拿、拔罐即通过刺激腧穴疏通经络、调和气血而治病保健。腧穴分类有特定穴之制：五输穴、原穴、络穴、郄穴、募穴、背俞穴等各司其职，是针灸学的核心内容。',related:['jingluo','ziwu-liuzhu']},
  {slug:'wuzang-liufu',name:'五脏六腑',pinyin:'Wǔ Zàng Liù Fǔ',english:'Five Viscera and Six Bowels',category:'zhongyi',shortDesc:'五脏藏精主化，六腑传化水谷，表里相配成整体。',detail:'五脏六腑是中医对人体内脏的总称。五脏即心、肝、脾、肺、肾，主藏精气而不泻，是生命活动的根本，各有职司：心主血脉神志，肝主疏泄藏血，脾主运化统血，肺主气司呼吸，肾主水藏精。六腑即胆、胃、小肠、大肠、膀胱、三焦，主受盛传化水谷而不藏。脏与腑表里相配（如心配小肠），与五体、五官、情志相应，构成以五脏为中心、内外一体的生理系统，中医辨证不离五脏六腑。',related:['cangxiang','qixue-jinye','wuxing-shengke-chengwu']},
  {slug:'qixue-jinye',name:'气血津液',pinyin:'Qì Xuè Jīn Yè',english:'Qi, Blood and Body Fluids',category:'zhongyi',shortDesc:'构成与维持生命的基本物质：气为动力，血为营养，津液为水液。',detail:'气血津液是中医所说的构成人体并维持生命活动的基本物质。气无形而动，是生命的动力，有元气、宗气、营气、卫气之分，主推动、温煦、固摄、防御；血有形而濡，主营养滋润全身；津液是体内一切正常水液的总称，主滋润濡养。三者相互依存：气能生血、行血、摄血，血能载气养气，津血同源。气血津液充足流畅则健康，亏虚或运行失常则百病丛生，故调理气血津液是中医治病的大法。',related:['wuzang-liufu','cangxiang','qiji']},
  {slug:'qiji',name:'气机',pinyin:'Qì Jī',english:'Qi Movement',category:'zhongyi',shortDesc:'气的运动机制，基本形式为升、降、出、入。',detail:'气机指气的运动机制与状态。气的运动形式主要有升、降、出、入四种：升者上行，降者下行，出者外达，入者内守，四者协调则气机调畅，生命活动正常。各脏腑的气机各有特点，如脾主升清、胃主降浊、肺主宣发肃降、肝主疏泄升发。若升降出入失常，便会出现气滞（运行不畅）、气逆（当降反升）、气陷（当升反降）、气闭气脱等病机，表现为痞满、咳喘、眩晕、脏器下垂诸症，调理气机为中医治法之要。',related:['qixue-jinye']},
  {slug:'wuxing-shengke-chengwu',name:'五行生克乘侮',pinyin:'Wǔ Xíng Shēng Kè Chéng Wǔ',english:'Five-Phase Generation, Control, Overacting and Insulting',category:'zhongyi',shortDesc:'木火土金水相生相克为常，相乘相侮为病的理论。',detail:'五行生克乘侮是中医运用五行说明脏腑关系的理论。相生即木生火、火生土、土生金、金生水、水生木，如肝木济心火，母子相生；相克即木克土、土克水、水克火、火克金、金克木，如肝木疏脾土，维持平衡，相生相克属正常制化。相乘是克制太过，如肝气过旺乘脾土致腹痛泄泻；相侮是反克，如肝木过旺反侮肺金致咳逆。相乘相侮皆属病理，临床以生克乘侮推演脏腑传变，指导治则。',related:['wuzang-liufu','cangxiang']},
  {slug:'wuyun-liuqi',name:'五运六气',pinyin:'Wǔ Yùn Liù Qì',english:'Five Circuits and Six Qi',category:'zhongyi',shortDesc:'运气学说：以干支推算气候年景与疾病流行的理论。',detail:'五运六气简称运气，是《黄帝内经》运气七篇所载的学说，以天干地支为工具推算每年气候特点与疾病流行规律。五运指木、火、土、金、水五种运，分中运（大运，统主全年）、主运、客运；六气指风、热（君火）、火（相火）、湿、燥、寒六气，分主气与客气。以天干定五运、地支定六气，配合司天在泉与客主加临，可推知六十年一个周期内的气候变化与发病趋向，用于预测时令病与指导用药，属中医「天人相应」思想的集中体现。',related:['wuyun-sanji','sitian','taiguo-buji']},
  {slug:'wuyun-sanji',name:'五运三纪',pinyin:'Wǔ Yùn Sān Jì',english:'Three Annual Cycles of the Five Circuits',category:'zhongyi',shortDesc:'岁运的三种年景：平气、太过、不及之纪。',detail:'五运三纪是运气学说对岁运（中运）三种年景的概括。《素问·五常政大论》将五运之年分为三纪：平气之纪，岁运无过无不及、与时相得，气候平和，如木之「敷和」；太过之纪，运气亢盛、气化早至，如木之「发生」，易致本脏亢而为病；不及之纪，运气不足、气化晚至，如木之「委和」，所不胜之气易来乘之。三纪决定全年气候基调与发病倾向，是运气推算与时令辨证的重要依据。',related:['wuyun-liuqi','taiguo-buji','sitian']},
  {slug:'taiguo-buji',name:'太过不及',pinyin:'Tài Guò Bù Jí',english:'Excess and Deficiency (of Annual Qi)',category:'zhongyi',shortDesc:'判断岁运盛衰：太过则本气亢盛，不及则本气衰弱。',detail:'太过与不及是运气学说判断岁运强弱的术语。岁运太过之年，本气偏亢、气候早至，如木运太过则风气流行，肝木偏胜，脾土受乘，人易患头痛眩晕、胁满吐泻等肝旺乘脾之病；岁运不及之年，本气不足、气候迟至，如木运不及则燥金乘之，金气偏胜，人易患燥咳、筋痿等症。判断岁运太过不及，可预测全年气候变化与脏腑发病趋向，指导用药宜忌，是运气学说的基本功夫。',related:['wuyun-liuqi','wuyun-sanji','kezhu-jialin']},
  {slug:'sitian',name:'司天',pinyin:'Sī Tiān',english:'Celestial Manager (Upper Governing Qi)',category:'zhongyi',shortDesc:'客气中主上半年气候之气，由岁支决定。',detail:'司天是六气客气中主管上半年（前三步）气候之气，位于三之气的位置，统管天气。《素问》说「司天在上」，它由年支决定：子午之岁少阴君火司天，丑未之岁太阴湿土司天，寅申之岁少阳相火司天，卯酉之岁阳明燥金司天，辰戌之岁太阳寒水司天，巳亥之岁厥阴风木司天，六年一循环。司天之气决定当年上半年气候特点与疾病倾向，如君火司天之年上半年偏热，易发温热病。',related:['zaiquan','keqi','wuyun-liuqi']},
  {slug:'zaiquan',name:'在泉',pinyin:'Zài Quán',english:'Earth Spring (Lower Governing Qi)',category:'zhongyi',shortDesc:'客气中主下半年气候之气，与司天相对相应。',detail:'在泉是六气客气中主管下半年（后三步）气候之气，位于终之气的位置，与司天相对，犹如司天在下临之泉。在泉之气亦由岁支决定，与司天总属三阴三阳相对相配：如子午年少阴君火司天，则阳明燥金在泉；丑未年太阴湿土司天，则太阳寒水在泉。司天在上主上半年，在泉在下主下半年，上下相合反映全年气候全貌；推病亦分司天在泉所主，指导随季节用药，是运气学说的基本内容。',related:['sitian','keqi','wuyun-liuqi']},
  {slug:'zhuqi',name:'主气',pinyin:'Zhǔ Qì',english:'Host Qi',category:'zhongyi',shortDesc:'一年六步固定不变之气，反映正常季节气候节律。',detail:'主气是运气学说中主管一年正常气候节律的六步之气，年年固定不变。自大寒日起，按厥阴风木、少阴君火、少阳相火、太阴湿土、阳明燥金、太阳寒水之序，每步约六十日八十七刻半，分主六个时段：初之气风木主春，二之气君火、三之气相火主夏，四之气湿土主长夏，五之气燥金主秋，终之气寒水主冬。主气体现一年温热凉寒的正常递变，是推算客气与判断气候异常的基准。',related:['keqi','kezhu-jialin','wuyun-liuqi']},
  {slug:'keqi',name:'客气',pinyin:'Kè Qì',english:'Guest Qi',category:'zhongyi',shortDesc:'随岁支年年轮转的六步之气，反映异常气候。',detail:'客气是运气学说中随年份变化、年年不同的一年六步之气，体现当年气候的异常与特殊变化。客气也按三阴三阳次序运行，但以其司天之气定位，司天居三之气，在泉居终之气，其余四气分列前后，六年一轮转。客气之中以司天、在泉最为关键，主宰全年气候大势。把客气加临于固定的主气之上，比较其生克逆顺，即可推知各时段气候的偏常与疾病发生，是运气预测的主要方法。',related:['zhuqi','sitian','kezhu-jialin']},
  {slug:'kezhu-jialin',name:'客主加临',pinyin:'Kè Zhǔ Jiā Lín',english:'Guest-Host Combination',category:'zhongyi',shortDesc:'以客气加临主气之上，比较生克逆顺以断气候顺逆。',detail:'客主加临是运气学说推演气候的具体方法：将年年变化的客气，加在年年固定的主气之上，看同一时段内客气与主气的五行生克关系，判断该时段气候的顺逆与疾病的易发。若客主之气相生或同气，为相得、顺，气候平和少病；若客气克主气或主气克客气而克制太过，为不相得、逆，气候反常易生疾疫。如主气风木之时遇客气燥金来克，则风木受抑、气候失和。客主加临是运气辨证的核心技法。',related:['keqi','zhuqi','sitian']},
  {slug:'tianfu',name:'天符',pinyin:'Tiān Fú',english:'Heavenly Talisman (Year)',category:'zhongyi',shortDesc:'岁运与司天之气五行相同之年，运气同化之一。',detail:'天符是运气学说中「运气同化」的一种年份：岁运（中运）的五行属性与当年司天之气的五行属性相同，如己丑、己未年，土运与太阴湿土司天同属土，即天符之年。天符之年运气相合、同气相求，气候变化专一而剧烈，发病往往急重，易流行与该气相应的病证，须提前防范。天符与岁会、太一天符、同天符、同岁会并称运气同化诸格，是《内经》用以衡量年景轻重、指导防治的重要概念。',related:['suihui','sitian','wuyun-liuqi']},
  {slug:'suihui',name:'岁会',pinyin:'Suì Huì',english:'Year Convergence (Year)',category:'zhongyi',shortDesc:'岁运与岁支五行相同之年，运气同化之平和者。',detail:'岁会是运气学说中「运气同化」的一种年份：岁运的五行属性与年支（岁支）本气的五行相同，如丁卯年木运临卯木，丙子年水运临子水，甲辰年土运临辰土，皆属岁会。岁会之年运与岁支同气相会，气候偏于平和稳定，变化较缓，疾病亦相对轻缓。若岁会又兼天符（运、气、支三者同气），则为最重的太一天符之年，气候与发病皆剧烈，须格外防范。',related:['tianfu','wuyun-liuqi','sitian']},
  {slug:'ziwu-liuzhu',name:'子午流注',pinyin:'Zǐ Wǔ Liú Zhù',english:'Midnight-Noon Ebb-Flow',category:'zhongyi',shortDesc:'气血依十二时辰流注十二经脉，按时开穴的针法。',detail:'子午流注是中医时间针灸学说。中医认为气血在十二经脉中的运行随昼夜十二时辰而盛衰流注，各有其时：寅时注肺，卯时注大肠，辰时注胃，巳时注脾，午时注心，未时注小肠，申时注膀胱，酉时注肾，戌时注心包，亥时注三焦，子时注胆，丑时注肝。依此配合天干地支与五行生克，推算经脉气血开阖之时，按时选取相应腧穴施针，称子午流注针法，是「因时制宜」思想在针灸中的运用，至今临床仍有效验。',related:['shuxue','jingluo']},
  {slug:'bagang-bianzheng',name:'八纲辨证',pinyin:'Bā Gāng Biàn Zhèng',english:'Eight-Principle Pattern Differentiation',category:'zhongyi',shortDesc:'阴阳表里寒热虚实八纲，辨证论治之总纲。',detail:'八纲辨证是中医辨证的总纲，以阴、阳、表、里、寒、热、虚、实八类证候归纳病情。阴阳为总纲：表、热、实属阳，里、寒、虚属阴；表里辨病位的深浅，寒热辨病性，虚实辨正邪的盛衰。临证先辨八纲以定大方向，如恶寒发热脉浮为表证，久病畏寒肢冷为里虚寒证，再结合脏腑、气血、六经等辨证，方能立法处方。八纲辨证提纲挈领，是中医各辨证方法共同的基础。',related:['liujing-bianzheng','sizhen','weiqi-yingxue']},
  {slug:'liujing-bianzheng',name:'六经辨证',pinyin:'Liù Jīng Biàn Zhèng',english:'Six-Channel Pattern Differentiation',category:'zhongyi',shortDesc:'张仲景所创：以太阳阳明少阳太阴少阴厥阴论外感病。',detail:'六经辨证是东汉张仲景《伤寒杂病论》创立的辨证体系，将外感热病的发生发展按太阳、阳明、少阳（三阳）与太阴、少阴、厥阴（三阴）六经归纳。三阳病多属表、属热、属实：太阳病为表证，阳明病为里热实证，少阳病为半表半里；三阴病多属里、属寒、属虚：太阴病脾虚寒湿，少阴病心肾阳虚或阴虚，厥阴病寒热错杂。六经各有提纲证候，可判断病位深浅、正邪消长与传变趋势，从而确定汗、吐、下、和、温、清诸法，是中医辨证论治的典范。',related:['bagang-bianzheng','weiqi-yingxue']},
  {slug:'weiqi-yingxue',name:'卫气营血',pinyin:'Wèi Qì Yíng Xuè',english:'Defense-Qi-Nutrient-Blood Differentiation',category:'zhongyi',shortDesc:'清代叶天士所创温病辨证：卫气营血四层传变。',detail:'卫气营血是清代名医叶天士为诊治温病创立的辨证纲领，将温热病邪由浅入深的传变分为卫、气、营、血四个层次。邪在卫分，病浅在表，症见发热恶寒、无汗或少汗；传入气分，里热炽盛，症见壮热口渴、汗出脉洪；深入营分，热伤营阴、扰乱心神，症见身热夜甚、斑疹隐隐、心烦谵语；深入血分，热盛动血，症见斑疹吐衄、抽搐神昏。据此立「在卫汗之，到气才可清气，入营犹可透热转气，入血直须凉血散血」的治疗大法。',related:['bagang-bianzheng','liujing-bianzheng']},
  {slug:'liuyin',name:'六淫',pinyin:'Liù Yín',english:'Six Pathogenic Factors',category:'zhongyi',shortDesc:'风寒暑湿燥火六种外感病邪，六气太过即成淫邪。',detail:'六淫指风、寒、暑、湿、燥、火六种外感病邪。正常情况下它们称六气，是万物生长的自然条件；若太过、不及或非其时而有其气，侵袭人体致病，便称六淫。六淫各有致病特点：风为百病之长，善行数变；寒性收引凝滞，易伤阳气；暑性炎热升散，多挟湿；湿性重浊黏滞，易困脾阳；燥性干涩，易伤津液；火（热）性炎上，易伤阴动血。六淫多从肌表口鼻而入，是外感病的主要病因，辨证须分六淫兼挟。',related:['sizhen','wuyun-liuqi']},
  {slug:'sizhen',name:'四诊',pinyin:'Sì Zhěn',english:'Four Diagnostic Methods',category:'zhongyi',shortDesc:'望闻问切四种诊察方法，四诊合参辨证论治。',detail:'四诊指中医诊察疾病的四种方法：望诊，观察神色形态、舌象与分泌物；闻诊，听声音（语言呼吸咳嗽）嗅气味；问诊，询问发病经过、症状、饮食二便与既往史；切诊，按脉搏、触按肌肤胸腹。四诊各有侧重，不可偏废，须「四诊合参」，将四方面信息综合分析，去伪存真，才能得出正确的证候判断。中医望闻问切之术源远流长，《难经》谓望而知之谓之神、闻而知之谓之圣、问而知之谓之工、切而知之谓之巧。',related:['bagang-bianzheng','cangxiang','liuyin']},
  // ===== 择日 (19) =====
  {slug:'zeri',name:'择日',pinyin:'Zé Rì',english:'Date Selection',category:'zexuan',shortDesc:'择吉术：为嫁娶丧葬动土出行等事选择吉利时日。',detail:'择日又称择吉、选日、看日子，是依天文历法与干支五行、神煞宜忌推算，为婚嫁、丧葬、动土、入宅、开市、出行等人生大事选择吉利时辰的术数。传统择日融汇建除十二神、二十八宿值日、黄道黑道、神煞冲煞与干支生克诸说，讲究「趋吉避凶、扶抑得宜」，因事择日、因人择日。择日之术源出古人对天时吉凶的敬畏，至今民间婚丧嫁娶动土仍多查黄历选日子，是影响最广的传统民俗之一。',related:['jianchu','huangdao-jiri','shensha','taisui']},
  {slug:'jianchu',name:'建除十二神',pinyin:'Jiàn Chú Shí Èr Shén',english:'Twelve Day Officers (Jian-Chu)',category:'zexuan',shortDesc:'建除满平定执破危成收开闭十二神轮值定吉凶。',detail:'建除十二神又称十二建除、十二建星，是择日体系的核心。依月支与日支推算，十二辰各有神名：建、除、满、平、定、执、破、危、成、收、开、闭，每日轮值一位，各主吉凶宜忌。民间口诀说「建满平收黑，除危定执黄，成开皆可用，闭破不相当」：除、危、定、执、成、开为黄道吉神，宜办事；建、满、平、收、闭、破为凶，须避忌。黄历「宜忌」多依当日所值建除之神而定，是择日最常用的框架。',related:['shier-zhiri','zeri','yuejian']},
  {slug:'shier-zhiri',name:'十二值日',pinyin:'Shí Èr Zhí Rì',english:'Twelve Day Officers (Daily Rotation)',category:'zexuan',shortDesc:'建除十二神轮流当值之日，黄历所标「值日」即此。',detail:'十二值日指建除十二神在十二地支日依次当值的说法，与建除十二神本为一事：以当月月建（值月地支）为准起算，第一日为建日，其后依次为除、满、平、定、执、破、危、成、收、开、闭，十二日一轮。如正月建寅，寅日为建、卯日为除，顺数轮转。当日所值之神称「值日神」，黄历每日所注「值日」即指此。值日神决定当日宜忌倾向，如开日宜开市开业，闭日忌安葬动土，是看日子先看的项目。',related:['jianchu','zeri','yuejian']},
  {slug:'huangdao-jiri',name:'黄道吉日',pinyin:'Huáng Dào Jí Rì',english:'Auspicious Yellow-Path Day',category:'zexuan',shortDesc:'青龙明堂金匮天德玉堂司命六神值日，诸事皆宜。',detail:'黄道吉日指青龙、明堂、金匮、天德、玉堂、司命六位吉神值日的日子。择日家将日辰配以十二天神，其中此六神值日称黄道日，主诸事顺遂、百无禁忌，宜嫁娶、开市、动土、出行等一切喜事；其余天刑、朱雀、白虎、天牢、玄武、勾陈六神值日则属黑道凶日。黄道之说源于古代天文择吉，以为日辰行经黄道吉区则天神护佑。黄历多标「黄道吉日」以劝人趋吉，民间办事喜庆最爱择之。',related:['heidao-xionri','zeri','jianchu']},
  {slug:'heidao-xionri',name:'黑道凶日',pinyin:'Hēi Dào Rì',english:'Inauspicious Black-Path Day',category:'zexuan',shortDesc:'天刑朱雀白虎天牢玄武勾陈六神值日，诸事不宜。',detail:'黑道凶日与黄道吉日相对，指天刑、朱雀、白虎、天牢、玄武、勾陈六位凶神值日的日子。古人以为黑道之日凶神当值，气场不利，嫁娶、动土、安葬、出行等大事皆宜避忌，宜静守、祭祀或处理闲杂事务，故黄历多标「诸事不宜」或仅宜小事。黄道黑道之分源于对日辰与天神运行关系的想象，是择日与黄历文化中最普及的吉凶观念之一。民间挑选日子先问「是不是黄道日」，可见其影响之深。',related:['huangdao-jiri','zeri','shensha']},
  {slug:'ershiba-xiu-zhiri',name:'二十八宿值日',pinyin:'Èr Shí Bā Xiù Zhí Rì',english:'Day Host of the 28 Mansions',category:'zexuan',shortDesc:'二十八宿轮流值日，各宿有吉凶宜忌，配日择吉。',detail:'二十八宿值日是择日与黄历的重要内容：二十八宿按角、亢、氐、房、心、尾、箕等次序每日轮值一宿，值日之宿各有吉凶属性与宜忌歌诀，如角宿值日宜嫁娶、造作，亢宿值日忌开市、出行之类。择日时以二十八宿值日配合建除十二神、黄道黑道合参，判断当日宜忌；黄历亦常标注当日「廿八宿」之名。此说源于星占——古人以月亮约二十八日行一周天、日行一宿，遂借星宿轮值附会人间吉凶，与星占分野之说相通。',related:['ershiba-xiu','jianchu','zeri']},
  {slug:'shensha',name:'神煞',pinyin:'Shén Shà',english:'Deities and Baleful Stars',category:'zexuan',shortDesc:'择日与命理中的吉凶神煞总称，宜忌之所由出。',detail:'神煞是择日、命理与风水中共用的吉凶神总称，体系庞大繁杂。吉神称神或贵神，如天德、月德、天赦、天喜、驿马、禄神等，值日则百事宜行；凶神称煞，如岁破、三煞、月破、空亡、白虎、五鬼、劫煞等，值日则须避忌。神煞或以干支推算，如太岁、月建；或从星占而来，如黄道黑道诸神。一张黄历的宜忌、冲煞、值神，便是当日神煞的综合呈现。择日之法千门万户，总不外趋吉神而避凶煞。',related:['suipo','sansha','kongwang','zeri']},
  {slug:'taisui',name:'太岁',pinyin:'Tài Suì',english:'Grand Duke Jupiter',category:'zexuan',shortDesc:'古人想象中主宰一年吉凶之神，六十甲子各有太岁。',detail:'太岁是民间信仰与择日中极重要的神煞。古人将木星（岁星）运行与地支相配，假想一颗与岁星反向而行的「太岁」，六十甲子每年各有一位太岁神当值。民俗以太岁所在方位为尊而不可冲犯，动土修造须避岁方，故有「太岁头上动土」之说；人的生肖与当年太岁相冲称「冲太岁」，相值称「犯太岁」或「本命年」，民俗以为须谨慎行事、禳解祈福。择日与黄历中的岁破、三煞皆以太岁为基准推算。',related:['suipo','sansha','zeri']},
  {slug:'suipo',name:'岁破',pinyin:'Suì Pò',english:'Year Breaker',category:'zexuan',shortDesc:'太岁所冲之方位或冲太岁之日辰，大凶宜避。',detail:'岁破有方位与日辰两义。方位上，太岁所冲之方为岁破方，如太岁在子（正北），则午（正南）为岁破方，古人以为此方当年不可兴造、移徙、安葬，触之冲犯太岁招灾；日辰上，与太岁地支相冲之日为岁破日，如子年逢午日、丑年逢未日，岁破日诸事不宜，最为择日所忌。岁破与太岁相对相冲，代表一年中气场最冲突的日子与方位，黄历遇岁破日多注「诸事不宜」，民间看日子必先避之。',related:['taisui','sansha','yuepo']},
  {slug:'sansha',name:'三煞',pinyin:'Sān Shà',english:'Three Baleful Stars',category:'zexuan',shortDesc:'劫煞灾煞岁煞三煞，依三合局定方，动土最忌。',detail:'三煞指劫煞、灾煞、岁煞三位凶煞，择日与风水皆重之。三煞依三合局与岁支推算方位：如申子辰年煞在南方巳午未，寅午戌年煞在北方亥子丑，巳酉丑年煞在东方寅卯辰，亥卯未年煞在西方申酉戌。三煞所在之方当年不可动土、修造、安葬，所谓「三煞方宜静不宜动」，冲犯则主灾祸，须以吉神制化或避而不用。凡起工动土，择日必先避开三煞日与三煞方，是择日家最常用的避忌。',related:['suipo','dongtu-zeri','zeri']},
  {slug:'yuepo',name:'月破',pinyin:'Yuè Pò',english:'Month Breaker',category:'zexuan',shortDesc:'月建所冲之日为月破日，逢冲气散，诸事不宜。',detail:'月破是择日常用的凶日：与当月月建相冲之日即为月破，如正月建寅则申日为月破，二月建卯则酉日为月破，依此类推，每月的月破日都在月建对面。古人认为月破之日冲气太盛、气场涣散，不利于聚合之事，嫁娶、开张、入宅、安葬等喜庆大事皆忌用，唯破旧立新、破除之事或可偶用。择日先看是否月破，如同先看是否岁破，二者一管月一管年，皆属冲气之忌，黄历多予标注。',related:['suipo','yuejian','zeri']},
  {slug:'kongwang',name:'空亡',pinyin:'Kōng Wáng',english:'Void (Kong Wang)',category:'zexuan',shortDesc:'干支纪日每旬所余二支为空亡，做事易落空之忌。',detail:'空亡是干支纪日纪年中由旬推算出的虚支。天干十位、地支十二位相配，每旬十日，一旬之末必余两支无干可配，如甲子旬中戌亥为空亡，甲戌旬中申酉为空亡，故称旬空。择日与命理皆忌空亡：择日逢空亡之日，谓做事徒劳、诸事落空，嫁娶出行宜避；命理中空亡主缘分虚浮、谋事多阻，然亦有「空亡逢合或冲则可解」之说。查空亡之法，看日柱在何旬，旬中无干之二支即空亡。',related:['zeri','shensha','chongsha']},
  {slug:'chongsha',name:'冲煞',pinyin:'Chōng Shà',english:'Clash and Baleful Direction',category:'zexuan',shortDesc:'黄历「冲XX煞X」：日支冲某生肖，某方为煞方。',detail:'冲煞是黄历每日标注的重要信息，格式如「冲猴煞北」：冲指当日地支与某一生肖（年支）相冲，六冲之对——子午、丑未、寅申、卯酉、辰戌、巳亥，故「冲猴」即当日地支为寅（虎），与申（猴）相冲，属猴者此日须避大事；煞指当日煞方，如「煞北」即北方为当日凶方，行事方向宜避之。冲煞用于提醒当事人当日与谁相冲、何方不利，是看日子须与当事人生肖配合的第一道手续，婚嫁尤其讲究。',related:['suipo','kongwang','jiaqu-zeri']},
  {slug:'sili-sijue',name:'四离四绝',pinyin:'Sì Lí Sì Jué',english:'Four Separations and Four Extinctions',category:'zexuan',shortDesc:'二分二至前一日为四离，四立前一日为四绝，忌大事。',detail:'四离四绝是民间择日与黄历共忌的特殊日子。四离日指春分、秋分、夏至、冬至四个节气的前一日——此四日为阴阳之气转换交接的极点，春分秋分昼夜平分、夏至冬至阴阳盛极将变，古人以为节气交变之隙气场不稳，忌嫁娶、远行、入宅等大事；四绝日指立春、立夏、立秋、立冬四个节气的前一日——春夏秋冬四季五行之气至此将绝而新气未生，故曰四绝，同样诸事不宜。黄历见四离四绝多注「大事勿用」，实为提醒人避开节令交接的临界日。',related:['zeri','heidao-xionri','ershisi-jieqi']},
  {slug:'yuejian',name:'月建',pinyin:'Yuè Jiàn',english:'Month Commander (Branch)',category:'zexuan',shortDesc:'值月地支称月建，正月建寅，为一月之主。',detail:'月建指干支纪月中值月的那个地支，如正月建寅、二月建卯、三月建辰，顺行至十二月建丑，所谓「斗柄指寅，天下皆春」。月建为一月之主，统管当月之令，择日诸法皆以月建为基准：建除十二神自月建日起算，月破即月建所冲之日，月厌、月煞等神煞亦由月建推出；命理中月支（月令）也最重，谓之提纲。黄历与择日推算年月吉凶，第一步就是确定年月干支与月建所在。',related:['jianchu','yuepo','zeri']},
  {slug:'jiaqu-zeri',name:'嫁娶择日',pinyin:'Jià Qǔ Zé Rì',english:'Marriage Date Selection',category:'zexuan',shortDesc:'婚嫁择吉：选黄道吉日并避生肖冲煞与诸凶煞。',detail:'嫁娶择日是民间最讲究的择日。除须选黄道吉日、避岁破月破与四离四绝外，还要合新郎新娘及双方父母的生肖，避开冲煞之日与三娘煞、杨公忌日等凶日；讲究的还推「大利月、小利月」，依女方生肖定嫁娶之月，并看周堂值日以定行礼时辰。民俗又忌在无春之年（无立春之年）嫁娶，喜双春之年。婚期既定，诸事如安床、上头、迎亲皆随吉时而行。择吉婚配寄托了白头偕老、家宅兴旺的美好愿望。',related:['zeri','chongsha','huangdao-jiri']},
  {slug:'dongtu-zeri',name:'动土择日',pinyin:'Dòng Tǔ Zé Rì',english:'Ground-Breaking Date Selection',category:'zexuan',shortDesc:'修造动工择日：避三煞岁破土王，宜吉神黄道。',detail:'动土指修建房屋、破土开工，动土之日关系施工顺利与家宅安宁，故民间极重动土择日。择日要点：须选黄道吉日，宜天德、月德、岁德等吉神当值；忌岁破、月破、三煞方日，尤其动土方位不可冲犯太岁与三煞所在；还要避开「土王用事」之日（立春立夏立秋立冬前十八日，土气当旺，忌破土）。动工前民间多设香案祭土地神，谓之安土、祭土，祈求工程平安。奠基、上梁亦各有吉时讲究。',related:['sansha','taisui','zeri']},
  {slug:'anzang-zeri',name:'安葬择日',pinyin:'Ān Zàng Zé Rì',english:'Burial Date Selection',category:'zexuan',shortDesc:'下葬择吉：避重丧三丧诸凶，合仙命山向选吉课。',detail:'安葬择日属丧葬礼俗的重要环节。民俗以为葬日吉凶关乎亡者安息与子孙祸福，故须择吉下葬：宜选黄道吉日，忌岁破、月破、重丧日、三丧日与复日等凶日，避开太岁、三煞所在方位；讲究的还要配合亡者「仙命」（生卒年干支）与坟地山向，推求不冲不克的上吉日课，并选入殓、出殡、落葬各时辰。若一时不得吉日，俗有停柩待吉或先寄葬之变通。安葬择日事涉孝道与风水，民间奉行最谨。',related:['zeri','sansha','suipo']},
  {slug:'yanggong-jiri',name:'杨公忌日',pinyin:'Yáng Gōng Jì Rì',english:'Master Yang Taboo Days',category:'zexuan',shortDesc:'传说杨筠松所定十三凶日，忌出行开市诸事。',detail:'杨公忌日相传为唐代风水名师杨筠松（杨救贫）所定，全年共十三天：正月十三、二月十一、三月初九、四月初七、五月初五、六月初三、七月初一、七月二十九、八月二十七、九月二十五、十月二十三、十一月二十一、十二月十九。民俗以为杨公忌日诸事不宜，忌出行、远游、开张、嫁娶、动土，谓「杨公忌日，百事禁忌」，出门办事多避之。此忌日流传极广，各地黄历多予标注，是影响民间日程安排的少数固定忌日之一。',related:['zeri','heidao-xionri','jiaqu-zeri']},
  // ===== 梦占 (10) =====
  {slug:'mengshu',name:'梦书',pinyin:'Mèng Shū',english:'Dream Manuals',category:'meng',shortDesc:'记录占梦之说与梦例的书籍，古人解梦的主要工具。',detail:'梦书是古代记录梦境吉凶之说、分类编排梦象解释的书籍，历代多有编纂，如《黄帝长柳占梦》、敦煌遗书《解梦书》以及后世托名周公的各种梦书。梦书一般按梦象分门别类——天文、地理、人事、器物、禽兽、花果等，每类一句断吉凶，如「梦见日月者大贵」「梦见大水者财来」之类。梦书内容多据占梦经验、民俗信仰与同象联想编成，虽近俚俗，却是研究古代梦信仰与民俗心理的第一手材料。',related:['zhanmeng','zhougong-jiemeng','mengleixing']},
  {slug:'zhanmeng',name:'占梦',pinyin:'Zhān Mèng',english:'Dream Divination',category:'meng',shortDesc:'古代方术之一，解说梦象以推断吉凶祸福。',detail:'占梦是中国最古老的方术之一，指通过对梦象的解释推断吉凶祸福。占梦起源极早，殷商甲骨卜辞中已有占梦记录，周代设专职占梦官，为天子诸侯占断梦兆；《左传》《史记》多载占梦应验之事。占梦之法有直解（梦吉断吉）、反说（梦凶反吉）、象喻（取梦中物象寓意）、谐音（谐音转义）等，又结合做梦者身份、梦时情境与五行学说。占梦术贯穿王侯政治与民间生活，是古代梦文化信仰的核心，历代梦书皆由此生。',related:['mengshu','jiemeng','mengzhao']},
  {slug:'jiemeng',name:'解梦',pinyin:'Jiě Mèng',english:'Dream Interpretation',category:'meng',shortDesc:'对梦象作解释以测吉凶的活动，俗称圆梦。',detail:'解梦又称圆梦，指对所作之梦进行解释、推断吉凶的活动，与占梦义近而更侧重事后圆说。解梦者依梦书所载、梦象特征、梦境情感与做梦者处境推衍吉凶，讲究梦象与时令、干支、身份相合，故同一梦对不同人有不同说法。古人又谓梦有真假，须察梦因：心思专注而梦易应验，恍惚偶梦多不足凭，所谓「梦有五不占，占有五不验」。解梦之术虽属迷信，却曲折反映了古人对心理活动与命运的思考。',related:['zhanmeng','mengshu','mengzhao']},
  {slug:'zhougong-jiemeng',name:'周公解梦',pinyin:'Zhōu Gōng Jiě Mèng',english:'Duke of Zhou Dream Interpretation',category:'meng',shortDesc:'托名周公的民间解梦书，流传最广的梦书通名。',detail:'周公解梦是民间流传最广的解梦书通名，托名西周周公旦而作，实为历代占梦之说层层增补的汇编。其书把梦境按天文、地理、人事、器物、饮食、飞禽走兽等门类编排，逐条断以吉凶，如「梦见日月照身，大贵」「梦见棺木，得官」「梦见牙齿落，主孝服」之类。孔子有「吾不复梦见周公」之语，周公遂成占梦的象征性人物。此书虽俚俗庞杂，却代代翻刻、家喻户晓，今人解梦仍多援引，是民间梦文化的最大载体。',related:['mengshu','jiemeng','mengleixing']},
  {slug:'mengleixing',name:'梦的类型',pinyin:'Mèng De Lèi Xíng',english:'Seven Types of Dreams',category:'meng',shortDesc:'直梦象梦因梦想梦精梦反梦病梦，古人对梦的七分法。',detail:'古人把梦归纳为七种类型：直梦，梦中所见与后来发生的事直接相符；象梦，以象征寓意示兆，如梦日而生贵子；因梦，因生理或环境感触而成梦，如饥则梦食、寒则梦衣；想梦，日有所思、夜有所梦；精梦，思虑专注凝想过度而结想成梦；反梦，梦吉反凶、梦凶反吉，所谓梦福得祸、梦祸得福；病梦，脏腑气血失调所致之梦，如《内经》所说阴盛梦涉大水。七分法概括了梦的成因、性质与兆应，是古代梦学最有体系的分类。',related:['mengshu','yinyang-mengshuo','zhouli-liumeng']},
  {slug:'yinyang-mengshuo',name:'阴阳梦说',pinyin:'Yīn Yáng Mèng Shuō',english:'Yin-Yang Theory of Dreams',category:'meng',shortDesc:'以阴阳盛衰释梦的中医理论：阴盛梦水，阳盛梦火。',detail:'阴阳梦说是中医以阴阳学说解释梦象的理论，见于《黄帝内经》。经言：阴气盛则梦涉大水而恐惧，阳气盛则梦大火而燔灼，阴阳俱盛则梦相杀毁伤；上盛则梦飞，下盛则梦堕；甚饥则梦取，甚饱则梦予；肝气盛则梦怒，肺气盛则梦哭。此说认为梦是脏腑阴阳气血盛衰变化在睡眠中的反映，梦象可作为诊察身体状态的线索，把梦从神鬼吉凶之说拉到人身生理之上，是中国梦学中最具科学精神的一支。',related:['mengleixing','mengzhao','cangxiang']},
  {slug:'zhouli-liumeng',name:'周礼六梦',pinyin:'Zhōu Lǐ Liù Mèng',english:'Six Dreams of the Rites of Zhou',category:'meng',shortDesc:'《周礼》载占梦官所掌六梦：正恶思寤喜惧。',detail:'周礼六梦出自《周礼·春官》，记周代设占梦官「掌其岁时，观天地之会，辨阴阳之气，以日月星辰占六梦之吉凶」。六梦为：正梦，平居无事而自然之梦；噩梦，惊愕恐怖之梦；思梦，因思念而成之梦；寤梦，半睡半醒、似梦非梦之觉；喜梦，因喜悦而梦；惧梦，因恐惧而梦。六梦从情志心境与睡境分类，并谓「以日月星辰占梦」，可见周代占梦已与星占历法结合，是先秦官方的梦学体系，为后世梦论之祖。',related:['mengleixing','zhanmeng','mengzhao']},
  {slug:'zhuangzhou-mengdie',name:'庄周梦蝶',pinyin:'Zhuāng Zhōu Mèng Dié',english:'Zhuangzi Butterfly Dream',category:'meng',shortDesc:'《庄子》寓言：不知庄周梦蝶还是蝶梦庄周。',detail:'庄周梦蝶出自《庄子·齐物论》：庄周梦中化为蝴蝶，翩翩然自得其乐，全然忘了自己是庄周；忽然醒来，惊觉自己分明是庄周。于是庄子发问：不知是庄周梦见了蝴蝶，还是蝴蝶梦见了庄周？此寓言借梦与觉的界限难分，探讨物我同化、是非两忘的境界，即「齐物」之旨。后世以庄周梦蝶喻人生如梦、物我皆幻，又引申为逍遥自在的意象，李白、李商隐等诗人屡用之，是中国梦文化中最著名的一则哲理故事。',related:['mengleixing','dao']},
  {slug:'mengzhao',name:'梦兆',pinyin:'Mèng Zhào',english:'Dream Omen',category:'meng',shortDesc:'古人以梦为精气所感可兆吉凶，梦象即徵兆。',detail:'梦兆指古人相信梦能预示吉凶的观念，又称梦徵。古人认为梦是「精气动」「神有所遇」的表现，梦象往往与未来之事相应，故有吉梦凶梦之说：梦日月、龙蛇、冠冕为贵兆，梦堕井、流血、丧服为凶兆。帝王感生传说多附会奇梦，如汉高祖之母梦遇神人而孕；科举时代士子亦重梦笔生花之类吉梦。梦兆信仰是占梦术存在的前提，古人据梦象趋吉避凶、禳解祈福，虽属迷信，却留下大量与梦相关的民俗与文献。',related:['zhanmeng','mengshu','tuomeng']},
  {slug:'tuomeng',name:'托梦',pinyin:'Tuō Mèng',english:'Dream Message from the Deceased',category:'meng',shortDesc:'民俗信仰：亡者祖先神佛在梦中显现嘱托警示生者。',detail:'托梦是民间普遍信仰的现象，指逝去的亲人、祖先或神明在生者梦中显现，有所嘱托、请求或警示，如亡亲托梦诉说缺衣少食、祖先托梦指示迁坟护佑、神明托梦示警禳解等。民俗认为托梦多发生在至亲之间，或因思念感应，或因阴灵有求，故常于清明、中元等节或梦后设祭超度、还愿了事。托梦与占梦不同，重在灵验叙事而非吉凶分类，是民间信仰中沟通阴阳的重要方式，戏曲小说中多有演绎。',related:['mengzhao','zhanmeng','mengshu']},
  // ===== 星占 (13) =====
  {slug:'qizheng-siyu',name:'七政四余',pinyin:'Qī Zhèng Sì Yú',english:'Seven Governors and Four Remnants',category:'zhanxing',shortDesc:'日月五星为七政，罗睺计都月孛紫气为四余。',detail:'七政四余是中国传统星占与星命术的核心体系。七政又称七曜，指太阳、太阴（月）与金木水火土五星；四余指罗睺、计都、月孛、紫气四颗「隐曜」——非实有之星，而为推算黄白道交点、月行迟疾等所设的虚点。七政四余按周天宫度运行，配以十二宫、二十八宿，推算人的命局贵贱，即所谓「星宗」「果老星宗」之术。其法唐宋时受印度历算影响而完备，与八字并行为古星命两大流派。',related:['jiuyao','xingmingshu','ershiba-xiu']},
  {slug:'jiuyao',name:'九曜',pinyin:'Jiǔ Yào',english:'Nine Luminaries',category:'zhanxing',shortDesc:'日月五星加罗睺计都，星占与星命常用之曜。',detail:'九曜指日月与金木水火土五星（七政）再加罗睺、计都二曜。罗睺、计都本为印度天文学中推算日月交食的黄白道升交点、降交点，传入中国后被列入星曜信仰，称蚀神；佛道二教与民间星命皆用九曜照命之说，谓人一生各年由不同星曜值照，吉凶不同，故有「九曜当头」「罗睺计都临命」等忌说。在九曜之上再加月孛、紫气，则为十一曜，是七政四余推命的完整星曜系统。',related:['qizheng-siyu','xingmingshu','tianren-ganying']},
  {slug:'suixing-jinian',name:'岁星纪年',pinyin:'Suì Xīng Jì Nián',english:'Jupiter Cycle Year-Naming',category:'zhanxing',shortDesc:'以木星运行周期纪年：岁星十二年一周天、一年一次。',detail:'岁星即木星，古人观察到它约十二年运行一周天，遂将周天自西向东分为十二段（十二次），岁星每年行经一次，以其所在星次纪年，称岁星纪年。但岁星实际周期约11.86年，运行稍快，积久便与星次不合，产生「超辰」之弊，于是古人另设一个与岁星背道而驰、匀速运行的假想星体「太岁」，以太岁所在十二辰纪年，并配以摄提格、单阏、执徐等岁名，称太岁纪年，后世干支纪年即由此演变而来。',related:['shier-xingci','taisui','ganzhi-jinian']},
  {slug:'shier-xingci',name:'十二星次',pinyin:'Shí Èr Xīng Cì',english:'Twelve Jupiter Stations',category:'zhanxing',shortDesc:'黄道附近周天十二分区，配十二地支与二十八宿。',detail:'十二星次是古人沿黄道将周天划分的十二个分区，自西向东依次为星纪、玄枵、娵訾、降娄、大梁、实沈、鹑首、鹑火、鹑尾、寿星、大火、析木，每区含若干星宿，与十二地支、十二辰相配，如星纪配丑、玄枵配子。岁星每年行一次，故星次用以纪年；星次又与二十八宿分野结合，用于占断各地吉凶。十二星次划分反映古人对日月五星运行背景的细致观测，是天文坐标与星占框架的重要基础。',related:['suixing-jinian','ershiba-xiu','fenyu']},
  {slug:'ershiba-xiu',name:'二十八宿',pinyin:'Èr Shí Bā Xiù',english:'Twenty-Eight Mansions',category:'zhanxing',shortDesc:'黄赤道附近二十八组恒星，分属四象各七宿。',detail:'二十八宿是古人选取黄道赤道附近的二十八组恒星作为坐标，称二十八宿，按方位分属四象，每象七宿：东方苍龙七宿为角、亢、氐、房、心、尾、箕；北方玄武七宿为斗、牛、女、虚、危、室、壁；西方白虎七宿为奎、娄、胃、昴、毕、觜、参；南方朱雀七宿为井、鬼、柳、星、张、翼、轸。月亮约二十八日行一周天、日行一宿，故二十八宿用于纪日、测候；配十二星次分野，又是星占、择日与风水的重要坐标。',related:['siling','ershiba-xiu-zhiri','fenyu']},
  {slug:'siling',name:'四灵',pinyin:'Sì Líng',english:'Four Divine Beasts',category:'zhanxing',shortDesc:'青龙白虎朱雀玄武四象，各辖二十八宿七宿。',detail:'四灵又称四象、四神，指东方青龙、南方朱雀、西方白虎、北方玄武四种神兽，源于远古星辰崇拜，分别统辖二十八宿中的七宿。四灵与方位、季节、颜色、五行相应：青龙属木主春色青，朱雀属火主夏色赤，白虎属金主秋色白，玄武属水主冬色黑。四灵广泛用于建筑（左青龙右白虎）、军阵（四象阵）、道教（四方护法神）与风水堪舆，汉代瓦当、画像石上四灵图形屡见不鲜，是中华文化最具代表性的天文动物形象。',related:['ershiba-xiu','sanyuan','xingguan']},
  {slug:'sanyuan',name:'三垣',pinyin:'Sān Yuán',english:'Three Enclosures',category:'zhanxing',shortDesc:'紫微太微天市三垣，与二十八宿合为全天星官体系。',detail:'三垣是古代星官体系中环绕北天极的三大天区：紫微垣居北天中央，是天帝居所，含北极、北斗等星官；太微垣在其东南，为天帝朝廷，含三台、五帝座等；天市垣在其西南，象征市集贸易，含市楼、列肆等。三垣以北极附近为中心，呈垣墙环抱之势，与二十八宿体系相配合，构成中国古代完备的「三垣二十八宿」全天分区。三垣之名充满人间帝王气象，反映了古人以天象比拟人间秩序的宇宙观。',related:['xingguan','ershiba-xiu']},
  {slug:'xingguan',name:'星官',pinyin:'Xīng Guān',english:'Asterisms (Star Officials)',category:'zhanxing',shortDesc:'古人组合邻近恒星而成的命名星群，以人间官制命名。',detail:'星官是古代天文学对恒星群的称谓：古人将邻近的恒星组合起来并命名，一官或一星或数星，统称星官。战国《甘石星经》已记数百星官，三国时陈卓综合三家，定星官二百八十三官、一千四百六十四星，为后世沿用。星官命名多取人间职官、器物、建筑与神话：三公、将军、文昌、织女、河鼓、贯索等，紫微垣即如一座天庭官署。星官是古代观测与占星的基本单位，星占即以星官所在的变动（如客星犯某官）断人间吉凶。',related:['sanyuan','ershiba-xiu','fenyu']},
  {slug:'fenyu',name:'分野',pinyin:'Fēn Yě',english:'Celestial Field Division',category:'zhanxing',shortDesc:'将天区与地上州国对应，观天象以断地方吉凶。',detail:'分野是古代星占的基本理论，把天上的星区与地上的州国对应起来：二十八宿、十二星次各有其对应的地面区域，如鹑火之次对应周地、大火之次对应宋地，某天区出现异常天象，便主对应地区有相应吉凶。分野之说起源甚早，《史记·天官书》《汉书·天文志》记载最详，除星次分野外还有以北斗、五星分配州郡诸说。分野把天文观测与人间祸福紧密勾连，是星占推断灾异发生地域的依据，体现了天人感应的整体宇宙观。',related:['ershiba-xiu','shier-xingci','tianren-ganying']},
  {slug:'wuxing-zhan',name:'五星占',pinyin:'Wǔ Xīng Zhàn',english:'Five-Planet Astrology',category:'zhanxing',shortDesc:'以五大行星运行天象占断吉凶，马王堆有专著。',detail:'五星占指以金木水火土五大行星的运行、亮度、颜色、方位及相互位置占断吉凶的术数。古称木星为岁星、火星为荧惑、土星为填（镇）星、金星为太白、水星为辰星，各配五行五方五帝。五星顺行、留守、逆行、犯宿等天象各有占辞，如「荧惑守心」主帝王之灾、「太白经天」主兵乱。1973年长沙马王堆汉墓出土帛书《五星占》，为现存最早的天文星占专著，记录了五星会合周期等精确数据，兼具科学与迷信双重价值。',related:['yinghuo-shouxin','qizheng-siyu','tianren-ganying']},
  {slug:'xingmingshu',name:'星命术',pinyin:'Xīng Mìng Shù',english:'Astrological Fate Calculation',category:'zhanxing',shortDesc:'依星曜宫度推算个人命运的术数，即星宗命法。',detail:'星命术是依天星推命的术数，广义泛指一切以星辰论命的方术，狭义指七政四余推命之法（又称星宗、五星术）。其法以人出生年月日时推算日月五星与四余所躔宫次、宿度，排成星盘，参看命宫、身宫与诸曜庙陷，论人贵贱寿夭、穷通祸福。星命术唐宋间随域外历算传入而大盛，与子平八字并称，后世合流，有《星命溯源》《果老星宗》等专著传世，对紫微斗数等后世命术亦多有影响。',related:['qizheng-siyu','jiuyao','ershiba-xiu']},
  {slug:'tianren-ganying',name:'天人感应',pinyin:'Tiān Rén Gǎn Yìng',english:'Heaven-Human Resonance',category:'zhanxing',shortDesc:'天与人相互感应：天象昭示人事，人事感动上天。',detail:'天人感应是古代星占与灾异学说共同的理论基础：古人认为天与人相通相感，天象的变化反映人间的治乱吉凶，人君修德则星明气和、祥瑞频现，失德则天垂灾异以示谴告，如日食、彗星、五星失行皆被视为上天示警。此说由先秦天命思想发展而来，汉代董仲舒加以系统阐发，成为官方政治学说，设天文机构观测星象、占候灾异，帝王亦因灾异而下诏罪己、修省政事。天人感应虽有迷信色彩，却在天人关系与政治哲学上影响深远。',related:['fenyu','wuxing-zhan']},
  {slug:'yinghuo-shouxin',name:'荧惑守心',pinyin:'Yíng Huò Shǒu Xīn',english:'Mars Guarding the Heart Mansion',category:'zhanxing',shortDesc:'火星留守心宿的天象，古占为大凶，主天子有灾。',detail:'荧惑守心是史书中最著名的大凶天象。荧惑即火星，古称主罚星、主兵丧；心指心宿，属东方苍龙七宿，其中间一星为天王（心大星），主天子。火星运行至心宿附近且留守不去，称荧惑守心，古占以为大凶，主帝王有灾、朝廷有变、兵乱丧亡，史官多郑重记录。传说宋景公时荧惑守心，太史劝其移祸于臣民，景公宁肯自当，三句善言竟使荧惑退舍。因应验之说牵动政局，史书所载亦有曲笔，然其作为凶兆符号影响深远。',related:['wuxing-zhan','ershiba-xiu','tianren-ganying']},
  // ===== 姓名学 (11) =====
  {slug:'xingmingxue',name:'姓名学',pinyin:'Xìng Míng Xué',english:'Nameology (Xingmingxue)',category:'xingming',shortDesc:'以姓名笔画五行与三才配置论吉凶的现代民俗学问。',detail:'姓名学是现代流行的姓名论断民俗学问，主体源自日本熊崎健翁创立的五格剖象法，二十世纪初传入中国后与汉字文化结合，广泛用于起名、改名。其法将姓名笔画数排出天格、人格、地格、外格、总格五格，每格配以数理五行与吉凶，再看天、人、地三才配置的生克，综合论断姓名优劣。姓名学虽非传统经典术数，但因简便易行、切合汉字实际而流传极广，民间起名多参考之，商家名号亦常请人推敲。',related:['wuge-pouxiangfa','sancai','bashiyi-shuli']},
  {slug:'wuge-pouxiangfa',name:'五格剖象法',pinyin:'Wǔ Gé Pōu Xiàng Fǎ',english:'Five-Grid Analysis Method',category:'xingming',shortDesc:'姓名学核心方法：以笔画数剖出五格论吉凶。',detail:'五格剖象法是姓名学的主流方法，由日本熊崎健翁于二十世纪初创制，后传入中国流行至今。其法将姓名的汉字笔画按规则计算出五格：天格、人格、地格、外格、总格，各格之数各配五行与数理吉凶（取一至八十一数理），人格为中枢，与天格、地格构成三才配置，观察五行生克以论断姓名的整体吉凶。剖象法讲究笔画须以康熙字典繁体为准，数理吉凶取尾数五行，虽属牵强附会，但因程式清晰、可操作性强而大行于世。',related:['xingmingxue','wuge','bashiyi-shuli']},
  {slug:'sancai',name:'三才',pinyin:'Sān Cái',english:'Three Talents (Heaven-Earth-Human)',category:'xingming',shortDesc:'姓名学三才指天格人格地格五行配置，本指天地人。',detail:'三才本指天、地、人三道，语出《易传》「三才之道」；姓名学借用其名，指姓名剖象中的天格、人格、地格三格及其五行。三格各配五行后，观其生克关系即为三才配置：天格属先天祖荫，地格属基础晚运? 具体而言，天格生人格、人格生地格，五行顺生相生者吉，主一生顺遂；人格克地格或三才克战，则主家庭不和、健康有损。故五格剖象须先看三才配置，凡相生无克者方为上选，起名书多列三才吉凶表供查。',related:['wuge','tiange','wuge-pouxiangfa']},
  {slug:'wuge',name:'五格',pinyin:'Wǔ Gé',english:'Five Grids',category:'xingming',shortDesc:'天格人格地格外格总格，姓名学剖象的基本框架。',detail:'五格是五格剖象法的基本框架，指从天格、人格、地格、外格、总格五个角度剖析姓名的数理。天格由姓氏笔画推算，主祖上遗传与早年环境；人格由姓末名首笔画合成，主一生之中心运程，称主运；地格由名字笔画推算，主前半生运程与家庭，称前运；外格主外在环境与社交助力；总格为全名笔画总和，主中年以后至晚年的总运。五格各有数理吉凶，互为生克，姓名学以五格俱全、配置相生者为吉名。',related:['tiange','renge','dige']},
  {slug:'tiange',name:'天格',pinyin:'Tiān Gé',english:'Heaven Grid',category:'xingming',shortDesc:'五格之首：由姓氏笔画所得，主祖荫与先天根基。',detail:'天格是五格中的第一格，由姓氏笔画数计算：单姓为姓氏笔画加一，复姓为两字笔画相加。姓名学认为天格代表祖先遗传、家族根基与早年成长环境，属先天带来的部分，本人难以选择与改变，故吉凶影响相对较小；但天格与人格的五行生克关系，却关乎一生际遇的顺逆，如天格生人格主得长辈提携。起名时多取天格数理平稳，不作主断，重点仍在人格与总格。',related:['wuge','renge','sancai']},
  {slug:'renge',name:'人格',pinyin:'Rén Gé',english:'Personality Grid',category:'xingming',shortDesc:'五格中枢：姓末名首笔画合成，主一生运程，称主运。',detail:'人格是五格剖象中的中枢之格，由姓氏末字笔画加名字首字笔画合成，代表自我、性格与一生运程的中心，称主运。姓名学认为人格数理吉凶对命运影响最大，人格之数吉则自立自强、成就可观，凶则多劳少成；人格五行与天格（主长辈）、地格（主家庭配偶）的生克构成三才配置，共同决定人际顺逆与健康倾向。故评姓名先看人格：数理须吉，五行须与上下相生，方为上选。',related:['wuge','sancai','tiange']},
  {slug:'dige',name:'地格',pinyin:'Dì Gé',english:'Earth Grid',category:'xingming',shortDesc:'五格之一：名字笔画所得，主前半生与家庭子女运。',detail:'地格是五格之一，由名字的笔画数计算：双字名两字笔画相加，单字名笔画加一，主中年前（约三十六岁前）的运程，称前运，也代表家庭环境、配偶与子女关系。姓名学认为地格数理吉则少年顺遂、家庭和乐、子女得力，凶则早年多艰或家宅不宁。地格与人格的生克尤须留意：地格克人格或人格克地格，皆主夫妻失和；地格生人格则主得配偶子女之助。',related:['wuge','renge','zongge']},
  {slug:'waige',name:'外格',pinyin:'Wài Gé',english:'External Grid',category:'xingming',shortDesc:'五格之一：主外在环境、社交关系与外部助力。',detail:'外格是五格之一，代表名字所体现的外在环境与社交层面，主社会关系、交际手腕与外部助力，称副运。外格数理吉则人缘佳、贵人多助、外出发展顺利；凶则易生是非口舌或遭人排挤。外格与人格的生克关系主本人与外界互动的顺逆，外格生人格主得朋友同僚之助。评名时五格须通盘考察：人格为主，总格管晚年，天格属先天，地格主前半生，外格司社交，数理皆吉且配置相生方为全美之名。',related:['wuge','zongge','renge']},
  {slug:'zongge',name:'总格',pinyin:'Zǒng Gé',english:'Total Grid',category:'xingming',shortDesc:'五格之一：全名笔画总和，主中年以后至晚年总运。',detail:'总格是五格中管束全局的一格，取姓名全部汉字笔画数相加而得，主中年以后以至晚年的整体运程，称总运，兼论断一生的总成就。姓名学认为总格数理吉则大器晚成、晚景丰隆、全名安泰；凶则中年后多波折、晚运不继。总格与人格一管总运一管主运，同为剖象重点。起名时先定人格总格之吉数，再配三才相生与外格得体，五格全吉而尤重人格总格，是五格剖象法的取舍大要。',related:['wuge','waige','dige']},
  {slug:'bihua-wuxing',name:'笔画五行',pinyin:'Bǐ Huà Wǔ Xíng',english:'Stroke-Number Five Phases',category:'xingming',shortDesc:'以汉字笔画个位数定五行：一二木三四火五六土七八金九零水。',detail:'笔画五行是姓名学确定汉字五行属性的常用方法：取汉字笔画数的个位数字配五行——一、二数属木，三、四数属火，五、六数属土，七、八数属金，九、零（十）数属水，其说与河图生成数、五行数序相承。起名时先看八字喜用何行，再选相应笔画数的字以求补益。除笔画法外，还有按字义、偏旁部首定五行之法，如「氵」旁属水、「火」旁属火；笔画法简便统一，流行最广，但一笔定五行亦有牵强处，诸法常参合使用。',related:['wuge','bashiyi-shuli','xingmingxue']},
  {slug:'bashiyi-shuli',name:'八十一数理',pinyin:'Bā Shí Yī Shù Lǐ',english:'Eighty-One Numerological Meanings',category:'xingming',shortDesc:'一至八十一各数的吉凶断语，五格剖象判吉凶之据。',detail:'八十一数理是姓名学的数理吉凶系统：把姓名笔画算出的各格之数，对应一至八十一数，每数各有名称、五行与吉凶断语，如吉祥运数、首领运数、财富运数、桃花运数以及孤寡运数、凶厄运数等，超过八十一者减去八十再取。此数理表系熊崎健翁据易数演为八十一数? 其源托于河洛易数，断语则如命理歌诀。姓名学以五格所得之数查数理吉凶，吉数多则名好，凶数多则名劣，是五格剖象法判断吉凶的直接依据。',related:['wuge-pouxiangfa','bihua-wuxing','wuge']},
  // ===== 易经补充 (20) =====
  {slug:'hetuluoshu',name:'河图洛书',pinyin:'Hé Tú Luò Shū',english:'Yellow River Map and Luo River Writing',category:'yijing',shortDesc:'易学两大数理图式：河图生成数，洛书九宫数。',detail:'河图洛书是易学象数的两大图式。传说伏羲时黄河出龙马负图，伏羲据河图画八卦；大禹时洛水出神龟负书，大禹据洛书定九州九畴。河图以白黑点表示一至十数，按五行生成排列，口诀「天一生水，地六成之」等，主生成；洛书布一至九数于九宫，口诀「戴九履一，左三右七，二四为肩，六八为足，五居中央」，主变化。后世以河图配先天八卦、洛书配后天八卦，河洛之学成为易学象数与术数（风水、奇门、择日）的数理根源。',related:['xiantian-bagua','houtian-bagua','taijitu']},
  {slug:'xiantian-bagua',name:'先天八卦',pinyin:'Xiān Tiān Bā Guà',english:'Former-Heaven Bagua',category:'yijing',shortDesc:'伏羲八卦：乾南坤北离东坎西，主对待，配先天数。',detail:'先天八卦又称伏羲八卦，据《说卦传》「天地定位，山泽通气，雷风相薄，水火不相射」排列：乾南、坤北、离东、坎西、兑东南、艮西北、震东北、巽西南，两两相对——乾对坤、离对坎、震对巽、艮对兑，阴阳相对、相反相成，故主「对待」，表示宇宙本然的对称结构。先天八卦又配先天数：乾一、兑二、离三、震四、巽五、坎六、艮七、坤八，合河图之数。先天为体，后天为用，先天八卦用于推演气数与先天命理。',related:['houtian-bagua','hetuluoshu','qian-trigram']},
  {slug:'houtian-bagua',name:'后天八卦',pinyin:'Hòu Tiān Bā Guà',english:'Later-Heaven Bagua',category:'yijing',shortDesc:'文王八卦：震东兑西离南坎北，主流行，配洛书九宫。',detail:'后天八卦又称文王八卦，据《说卦传》「帝出乎震，齐乎巽，相见乎离，致役乎坤，说言乎兑，战乎乾，劳乎坎，成言乎艮」排列：震东、兑西、离南、坎北、巽东南、乾西北、坤西南、艮东北，与八方四时相配——震为春、离为夏、兑为秋、坎为冬，主四时流转、万物生成，故主「流行」，表示事物运动变化之用。后天卦数即洛书数：坎一、坤二、震三、巽四、中五、乾六、兑七、艮八、离九。风水、奇门遁甲、择日等术数皆用后天八卦配九宫。',related:['xiantian-bagua','hetuluoshu','kan-trigram']},
  {slug:'liushisi-gua',name:'六十四卦',pinyin:'Liù Shí Sì Guà',english:'Sixty-Four Hexagrams',category:'yijing',shortDesc:'八卦两两相重而成，六十四卦三百八十四爻总天地变化。',detail:'六十四卦是《周易》的主体，由八卦两两相重而成，每卦六爻，共三百八十四爻（乾加用九、坤加用六）。卦分上下两体，上卦称上卦、外卦，下卦称下卦、内卦；六爻自下而上为初、二、三、四、五、上，各有爻位之义。六十四卦涵盖天地人三才万事万物的变化，排列分上经三十卦、下经三十四卦，起于乾坤终于既济未济。每卦有卦象、卦辞、爻辞，辅以十翼，构成完整的占筮与义理体系，是中华思想的核心经典。',related:['guaci','yaoci','tuanci']},
  {slug:'guaci',name:'卦辞',pinyin:'Guà Cí',english:'Hexagram Statement',category:'yijing',shortDesc:'总断一卦吉凶的文字，相传文王所系，故称文王卦辞。',detail:'卦辞是《周易》每卦之下总论全卦大义与吉凶的文字，相传为周文王被囚羑里时所作，故称文王卦辞。卦辞先举卦名，再断吉凶休咎，如乾卦卦辞「元亨利贞」、坤卦「元亨，利牝马之贞」、屯卦「元亨利贞，勿用有攸往，利建侯」，用词精约而义理宏深。解卦之法先观卦辞以明全卦之德与总断，再参爻辞察各爻之时位吉凶；卦辞又为彖传所逐句阐释，是理解六十四卦的门径。',related:['yaoci','tuanci','liushisi-gua']},
  {slug:'tuanci',name:'彖辞',pinyin:'Tuàn Cí',english:'Tuan Commentary',category:'yijing',shortDesc:'彖传：释卦辞、总论一卦之义，十翼之一。',detail:'彖辞又称彖传，因附于卦辞之后阐释其义，故称彖曰。彖辞专释一卦之卦名、卦象与卦辞，从上下卦的组合、中爻的位置与卦德三方面总论全卦大义，如释乾卦「大哉乾元，万物资始，乃统天」，释讼卦「上刚下险，险而健，讼」。彖辞旧传孔子所作，为十翼之一。读易先读彖：彖辞总断一卦之所以然，爻辞分述六爻之时位，彖统爻分，相辅相成。',related:['guaci','yaoci','xici']},
  {slug:'yaoci',name:'爻辞',pinyin:'Yáo Cí',english:'Line Statements',category:'yijing',shortDesc:'六十四卦三百八十四爻各系断语，相传周公所作。',detail:'爻辞是《周易》每卦六爻之下各系的文字，与卦辞合为经文。全书三百八十四爻各有爻辞，另乾坤二卦附用九、用六。爻辞多以具体物象人事设喻，揭示各爻之位与吉凶，如乾卦初九「潜龙勿用」、九二「见龙在田，利见大人」、上九「亢龙有悔」，借龙之潜见跃飞喻君子出处进退。相传爻辞为周公所作。解卦须爻位结合：看当位不当位、应不应、承乘关系与卦时，再参爻辞之象，方能得其旨趣。',related:['guaci','tuanci','liushisi-gua']},
  {slug:'xici',name:'系辞',pinyin:'Xì Cí',english:'Great Commentary (Xici)',category:'yijing',shortDesc:'系辞传：十翼中最重要之通论，总论易道精义。',detail:'系辞又称系辞传，分上下两篇，是《易传》中篇幅最大、义理最精的纲领性文献，旧传孔子所作。上篇总论易道大原：提出「易有太极，是生两仪，两仪生四象，四象生八卦」的宇宙生成论与「一阴一阳之谓道」的著名命题；下篇多论卦爻之义与圣人制器尚象，兼及「易与天地准，故能弥纶天地之道」。系辞阐发道器、变化、刚柔、吉凶悔吝诸义，把占筮之书提升为哲学经典，是研究易学思想与宇宙观的核心文献。',related:['tuanci','shuogua','taiji']},
  {slug:'daxiang-xiaoxiang',name:'大象小象',pinyin:'Dà Xiàng Xiǎo Xiàng',english:'Great and Small Images',category:'yijing',shortDesc:'象传分二：大象释卦象以君子修身，小象逐爻释辞。',detail:'象传是十翼之一，分大象传与小象传。大象传先举上下两卦之象（如乾为天，乾上乾下故曰「天行健」），再以「君子以」引出修身治世的启示，如「天行健，君子以自强不息」「地势坤，君子以厚德载物」，将自然法则化为人生准则，是义理易学最富教化意义的文字；小象传则逐爻解释爻辞，多以「潜龙勿用，阳在下也」式的断语阐明爻象吉凶之所以然。象者像也，象传借象明理，为观象玩辞的津梁。',related:['xici','tuanci','qian-trigram']},
  {slug:'shuogua',name:'说卦',pinyin:'Shuō Guà',english:'Discussion of the Trigrams',category:'yijing',shortDesc:'说卦传：专论八卦取象与方位，象数易学取象之据。',detail:'说卦传是十翼之一，专论八卦的象征体系。前半多言圣人作易「幽赞神明而生蓍」与三才六位之理；后半详列八卦所取之物象：乾为天、为圜、为君、为父、为玉、为金、为寒、为冰、为马、为龙，坤为地、为母、为布、为釜、为牛，以及震为雷、巽为风、坎为水、离为火、艮为山、兑为泽等，并推广至人伦、身体、器物、动物，触类旁通。另有「帝出乎震」一节言后天八卦方位。说卦是占筮取象与易学象数应用的直接依据，卦象体系由此扩展至万事万物。',related:['xici','houtian-bagua','zagua']},
  {slug:'xugua',name:'序卦',pinyin:'Xù Guà',english:'Order of the Hexagrams',category:'yijing',shortDesc:'序卦传：解说六十四卦排列次序相承相因之理。',detail:'序卦传是十翼之一，依次解说六十四卦排列顺序的理由，说明各卦前后相承、相反相成的关系。如释乾坤之后次以屯：「有天地然后万物生焉，盈天地之间者唯万物，故受之以屯；屯者盈也，屯者物之始生也」，释屯次蒙：「物生必蒙，故受之以蒙」，释泰否、损益、既济未济诸卦亦然。序卦传揭示六十四卦并非随意排列，而是一幅万物发生发展、循环往复的图景，体现《周易》整体观与变化观，为研读卦序与卦义提供了纲领。',related:['liushisi-gua','zagua','shuogua']},
  {slug:'zagua',name:'杂卦',pinyin:'Zá Guà',english:'Miscellaneous Hexagrams',category:'yijing',shortDesc:'杂卦传：打乱卦序，两两对举，一言点明卦义。',detail:'杂卦传是十翼之一，与序卦传不同，它不按六十四卦原序解说，而是将卦「杂糅」而聚，每两卦对举，以一两字或一两句点明要义与相反相成之德，如「乾刚坤柔，比乐师忧，临观之义，或与或求」「损益，盛衰之始也」。全文句式整齐、音韵铿锵，便于讽诵记忆，如一篇卦义歌诀。杂卦传从对待、转化的角度概括各卦德性，与序卦传一纵一横、一顺一杂，合观可窥六十四卦义理之大全，是学易入门的上好材料。',related:['xugua','shuogua','liushisi-gua']},
  {slug:'guaqi',name:'卦气',pinyin:'Guà Qì',english:'Hexagram Qi (Calendar System)',category:'yijing',shortDesc:'汉代易学以六十四卦配四时节气历法的学说。',detail:'卦气是汉代易学（孟喜、京房等）以六十四卦配合历法的学说。其法以坎、离、震、兑为四正卦，分主冬、夏、春、秋四时与二十四节气；其余六十卦配一年三百六十五日余，每卦值六日七分，称「六日七分」；又以复、临、泰、大壮、夬、乾、姤、遁、否、观、剥、坤十二消息卦配十二月与七十二候。卦气说把卦爻消息与阴阳消长、节气物候打成一片，是汉易象数与天人感应思想的结合，深刻影响后世易学、历法与术数。',related:['xiaoxi-gua','ershisi-jieqi','qishier-hou']},
  {slug:'xiaoxi-gua',name:'十二消息卦',pinyin:'Shí Èr Xiāo Xī Guà',english:'Twelve Sovereign Hexagrams',category:'yijing',shortDesc:'复临泰大壮夬乾姤遁否观剥坤十二卦配十二月。',detail:'十二消息卦又称十二辟卦、十二月卦，是卦气说的核心：以复、临、泰、大壮、夬、乾、姤、遁、否、观、剥、坤十二卦对应农历十二个月，各卦阴阳爻的消长恰合当月阴阳升降——十一月冬至复卦一阳来复，十二月临卦二阳，正月泰卦三阳开泰，二月大壮四阳，三月夬卦五阳，四月乾卦六阳纯全；五月姤卦一阴生，六月遁卦二阴，七月否卦三阴，八月观卦四阴，九月剥卦五阴，十月坤卦六阴纯阴。消息即阴阳消长，十二消息卦形象地概括了一年阴阳二气周而复始的节律。',related:['guaqi','dongzhi','qishier-hou']},
  {slug:'hugua',name:'互卦',pinyin:'Hù Guà',english:'Nuclear Hexagram',category:'yijing',shortDesc:'取一卦二三四爻与三四五爻交互而成的卦。',detail:'互卦是象数易学观卦之法：一卦六爻中，取第二、三、四爻组成下互卦，取第三、四、五爻组成上互卦，二卦相叠即得一新的六爻卦，称互卦或互体。如泰卦二三四爻为兑、三四五爻为震，互卦即雷泽归妹? 凡卦皆有互卦，互卦又自有互卦，可辗转相推。古人认为互卦反映原卦内部各爻交互作用的情状，可窥事物发展过程中间环节的隐微变化，断卦时常以互卦参看，如本卦主事之始、互卦主事之中，为筮法取象的重要补充。',related:['cuogua','zonggua','zhigua']},
  {slug:'cuogua',name:'错卦',pinyin:'Cuò Guà',english:'Opposite Hexagram',category:'yijing',shortDesc:'一卦六爻阴阳全变而成的卦，如乾错坤、坎错离。',detail:'错卦是象数易学观卦之法：将一卦六爻的阴阳全部反转（阳变阴、阴变阳），所得之卦即原卦的错卦，又称旁通卦、对卦。如乾卦六爻皆阳，错之则为六爻皆阴的坤卦；坎错离、震错巽、艮错兑，八纯卦两两成错。错卦体现阴阳对待、相反相成的两端，观错卦可知一卦的反面情状与变动趋势，如观乾之刚健须知坤之柔顺、观坎之险陷须知离之光明。占断时错卦用以参照，所谓「错者阴与阳相对」，成语「错综复杂」即源于错综二法。',related:['hugua','zonggua','qian-trigram']},
  {slug:'zonggua',name:'综卦',pinyin:'Zōng Guà',english:'Inverted Hexagram',category:'yijing',shortDesc:'一卦上下颠倒而成的卦，如屯综蒙、需综讼。',detail:'综卦是象数易学观卦之法：将一卦自下而上颠倒（倒置）而成的新卦，称综卦，又称覆卦、反卦、倒卦。如屯卦倒置为蒙卦，需卦倒置为讼卦，师卦倒置为比卦，故屯蒙、需讼、师比在六十四卦中皆前后相综。凡上下两体对称之卦（如乾坤、坎离、颐、中孚）颠倒不变，则无综。综卦表示从事物反面观之、或事势相覆反转之象，观综可察吉凶之颠倒转化与因果相续。错综互观，为周易象数断卦之基本功夫，后世成语「错综复杂」即出于此。',related:['cuogua','hugua','xugua']},
  {slug:'zhigua',name:'之卦',pinyin:'Zhī Guà',english:'Changed Hexagram',category:'yijing',shortDesc:'占筮中老阳老阴发动所变之卦，即变卦。',detail:'之卦是占筮术语，指起卦时因动爻变化而生成的卦，即俗所谓变卦。古筮以蓍草或金钱起卦，凡得老阳（九）则阳变阴，老阴（六）则阴变阳，原卦称本卦，动变之后的新卦称之卦，「之」训往，表示所往之势。如乾卦初九动，则乾之姤。断卦之法：本卦为事之始、当下之状，之卦为事之应、发展之果，两卦合观以断吉凶趋向；动爻之辞为主断，故有「观本卦以知现在，观之卦以知将来」之说。',related:['hugua','yaoci']},
  {slug:'taijitu',name:'太极图',pinyin:'Tài Jí Tú',english:'Taiji Diagram',category:'yijing',shortDesc:'阴阳鱼太极图与周敦颐太极图，易图学核心图式。',detail:'太极图是易学的重要图式，最著名者为阴阳鱼太极图：一圆之中黑白两仪回环互抱，各含对方之点，如双鱼追逐，象征阴阳互根、互生、消长与平衡——黑中有白点示阴中有阳，白中有黑点示阳中有阴，合之则为一太极。又有周敦颐《太极图说》所传的五层太极图，自「无极而太极」而下，历阴阳动静、五行顺布以至万物化生。太极图与河图洛书同属易图学，为宋以后理学与丹道共尊，今已成为中华文化最富代表性的符号。',related:['taiji','wuji-er-taiji','hetuluoshu']},
  {slug:'wuji-er-taiji',name:'无极而太极',pinyin:'Wú Jí Ér Tài Jí',english:'From Ultimateless to Supreme Ultimate',category:'yijing',shortDesc:'周敦颐《太极图说》首句，宋代理学宇宙论纲领。',detail:'无极而太极是周敦颐《太极图说》的开篇之语，也是宋明理学宇宙论的纲领：无极指无形无象的本然状态，太极指混沌未分、含具动静之机的元气，太极本于无极，体用一源。太极动而生阳，动极而静，静而生阴，阴阳既分，两仪立焉；阳变阴合而生水火木金土，五气顺布，四时行焉；五行一阴阳，阴阳一太极，万物生生而变化无穷。此说融合《易传》与道家思想，开宋明理学之先河，与丹道宇宙观相通。',related:['taiji','wuji','taijitu']},
  // ===== 黄历补充 (10) =====
  {slug:'huangli',name:'黄历',pinyin:'Huáng Lì',english:'Chinese Almanac',category:'huangli',shortDesc:'附注每日宜忌冲煞值神的历书，又称皇历老黄历。',detail:'黄历又称皇历、老黄历、通书，是古代官方颁行并流传民间的历书。历书除载年月日时、朔望与二十四节气外，还逐日标注干支、生肖、宜忌、冲煞、值神（建除十二神）、二十八宿、吉神凶煞等择日信息，供民众安排嫁娶、出行、动土、祭祀诸事。因传说历书为黄帝所创，或谓以黄色封面敬呈皇帝，故名黄历。今之黄历多为附择吉内容的农历历本，并加公历对照，是农历时间文化与择日民俗最普及的载体，至今仍为千家万户所用。',related:['nongli','zeri','ershisi-jieqi']},
  {slug:'nongli',name:'农历',pinyin:'Nóng Lì',english:'Chinese Lunar Calendar',category:'huangli',shortDesc:'中国传统阴阳合历：朔望定月、闰月调年、节气指导农时。',detail:'农历是中国的传统历法，属阴阳合历：月份按朔望月安排，以月相定朔望，平年十二个月约三百五十四日；年长须合回归年，故约两三年置一闰月，十九年七闰，使新年总在冬春之间。历中又含二十四节气，节气依太阳黄经而定，指示寒暑物候、指导农事，故称农历，旧称夏历。干支纪年、生肖属相、传统节日（春节、端午、中秋）皆随农历而行，至今农历仍与公历并行，是中国人生活节律与文化记忆的重要部分。',related:['shuowangyue','runyue','ershisi-jieqi']},
  {slug:'shuowangyue',name:'朔望月',pinyin:'Shuò Wàng Yuè',english:'Synodic Month',category:'huangli',shortDesc:'月相圆缺一周约29.53日，农历置月的基础周期。',detail:'朔望月是月球绕地球运行、月相圆缺变化一周的周期，从朔（月球与太阳相合、月不可见的新月）到下一次朔，平均约二十九日十二时四十四分（29.53日）。农历以朔日为月首（初一），望（满月）多在每月十五前后，故称朔望月。因朔望月不是整数日，农历月有大月三十日、小月二十九日之分，且每月初一必逢朔，十五前后必见圆月。朔望月与回归年并行为农历之两轮，一主月相一主年成，合之而成阴阳合历。',related:['nongli','runyue','xiazhi']},
  {slug:'runyue',name:'闰月',pinyin:'Rùn Yuè',english:'Intercalary Month',category:'huangli',shortDesc:'农历为协调朔望月与回归年所增设的月份，十九年七闰。',detail:'闰月是农历特有的置闰制度。一个回归年约三百六十五日五时，而十二个朔望月仅约三百五十四日，相差约十一日，若不置闰，历月将逐年提前、季节错乱。故农历约两三年加设一个月以补足差额，所加之月即闰月，如闰二月、闰六月。置闰之法为「十九年七闰」，闰月多置于没有中气的月份——二十四节气中十二中气各配一月，某月无中气即定为闰月。闰月的设置使农历新年始终在立春前后，农时节令得以与月相历长期吻合。',related:['nongli','shuowangyue','ershisi-jieqi']},
  {slug:'ershisi-jieqi',name:'二十四节气',pinyin:'Èr Shí Sì Jié Qì',english:'Twenty-Four Solar Terms',category:'huangli',shortDesc:'太阳黄经每15度一节气，共二十四，指导农时民俗。',detail:'二十四节气是把太阳周年视运动沿黄道等分为二十四段的节气系统，每十五度一节气，自春分点起算（现行以立春为首）。二十四节气分十二节与十二气（中气）相间：立春、惊蛰、清明、立夏、芒种、小暑、立秋、白露、寒露、立冬、大雪、小寒为节；雨水、春分、谷雨、小满、夏至、大暑、处暑、秋分、霜降、小雪、冬至、大寒为气。节气反映太阳位置与气候物候，指导农事安排，又与月相历配合构成阴阳合历；每个节气都有相应的民俗饮食与养生讲究，堪称中国人的时间哲学。',related:['qishier-hou','lichun','dongzhi']},
  {slug:'qishier-hou',name:'七十二候',pinyin:'Qī Shí Èr Hòu',english:'Seventy-Two Pentads',category:'huangli',shortDesc:'每节气分三候，全年七十二候，以物候现象纪时。',detail:'七十二候是古人把二十四节气进一步细分的时间体系：每节气分为三候，每候五日余，全年二十四节气共七十二候。每候皆以当时可见的物候现象命名，如立春三候为东风解冻、蛰虫始振、鱼陟负冰，惊蛰三候为桃始华、仓庚鸣、鹰化为鸠，冬至三候为蚯蚓结、麋角解、水泉动。七十二候以草木虫鱼鸟兽的变化标记时间流转，指示农时与养生，是古人长期观察自然的结晶，也是世界上最古老的物候历之一，对文学意象（如「一候」）亦影响深远。',related:['ershisi-jieqi','xiaoxi-gua','shujiu']},
  {slug:'sanfu',name:'三伏',pinyin:'Sān Fú',english:'Three Fu (Dog Days of Summer)',category:'huangli',shortDesc:'初伏中伏末伏合称三伏，一年最热时段，约三十至四十日。',detail:'三伏是全年最热的时段，分初伏、中伏、末伏。按传统历法推算：夏至后第三个庚日为初伏第一天，第四个庚日起为中伏，立秋后第一个庚日为末伏第一天，故有「夏至三庚数头伏」之说。初伏十日，末伏十日，中伏或十日或二十日，三伏共三十至四十天。伏者，谓阴气受阳气所迫藏伏地下，亦劝人伏藏避暑。三伏天气温最高、湿气最重，民间有贴三伏贴、饮伏茶、晒伏姜等习俗，中医亦重「冬病夏治」，趁三伏阳气最旺时调理宿疾。',related:['shujiu','xiazhi','liqiu']},
  {slug:'shujiu',name:'数九',pinyin:'Shǔ Jiǔ',english:'Counting the Nine (Winter)',category:'huangli',shortDesc:'自冬至起每九天一九，数至九九八十一天而春回大地。',detail:'数九是民间计冬盼春的习俗：自冬至日起，每九天为一个单位，称一九，依次数至九九八十一天，冬尽春来，故有「数九寒天」「九尽桃花开」之说。数九期间民间传唱九九歌，如「一九二九不出手，三九四九冰上走，五九六九沿河看柳，七九河开，八九雁来，九九加一九，耕牛遍地走」，生动记录冬春物候；文人雅士则绘九九消寒图，每日填染一笔，共八十一笔，图成而春至。数九谚语指导农事与养生，是黄历文化中富有人情味的计时智慧。',related:['dongzhi','sanfu','qishier-hou']},
  {slug:'ganzhi-jinian',name:'干支纪年',pinyin:'Gān Zhī Jì Nián',english:'Sexagenary Year Cycle',category:'huangli',shortDesc:'天干地支相配纪年，六十年一甲子循环往复。',detail:'干支纪年是以天干地支相配纪年的方法：十天干（甲乙丙丁戊己庚辛壬癸）与十二地支（子丑寅卯辰巳午未申酉戌亥）顺序相配，甲子、乙丑、丙寅……六十组为一周期，称六十甲子，周而复始。干支纪年起于东汉，元和二年（公元85年）后连续使用至今，成为贯穿中国历史的纪年系统，与十二生肖对应（子鼠丑牛等）。黄历、择日、八字推命皆以干支纪年定位年份，如甲辰年、乙巳年；干支纪年还派生出干支纪月、纪日、纪时，构成完整的干支时间体系。',related:['ganzhi-jiri','suixing-jinian','taisui']},
  {slug:'ganzhi-jiri',name:'干支纪日',pinyin:'Gān Zhī Jì Rì',english:'Sexagenary Day Cycle',category:'huangli',shortDesc:'以六十甲子逐日纪日，数千年连续不断，择日之基准。',detail:'干支纪日是以六十甲子逐日轮转纪日的方法，与月相、年号无关，连续不断，是中国使用时间最长的纪日系统。据学者考证，干支纪日自春秋鲁隐公三年（公元前720年）二月己巳日起有明确记载，沿用至今已两千七百余年从未间断，为世界纪日史所罕见。甲骨文中已普遍使用干支记日，可见其源远流长。黄历逐日标注干支，择日推算（建除、月破、空亡、冲煞）、命理排盘与星命择吉皆以当日干支为基准，是术数时间推算最根本的坐标。',related:['ganzhi-jinian','zeri','kongwang']},
];
